  /* ---------- 压力＆压强（基准：帕斯卡） ----------
     压力和压强是同一个量（力 ÷ 受力面积），中文里两套叫法都有人用，
     卡片名就把两个都写上。1 标准大气压 = 101325 Pa（精确定义）。
     毫米汞柱和托不是一回事，别混：托的定义是**精确的** 1 atm/760
     = 133.322368421… Pa；毫米汞柱按汞的密度和标准重力算出来是
     133.322387415 Pa，两者差在小数点后第 5 位。两个都留，各自按定义写。
     英寸汞柱 = 25.4 毫米汞柱（同族的英制写法）。

     另外几支：
       皮兹 pz —— MTS 制（米·吨·秒）的压强单位，1 pz = 1 sn/m² = 1000 Pa
       工程大气压 at —— 1 kgf/cm² = 98066.5 Pa（精确，别和 atm 混）
       磅每平方英尺 psf —— psi ÷ 144
       英寸水柱 inH₂O —— 25.4 毫米水柱，和上面那支同一个基准（4 ℃ 的水）

     ★ 三组「同值并存」，都是不同写法/叫法指向同一个数，两边都要留：
       百帕 hPa = 毫巴 mbar = 100 —— 气象学两套并行了几十年，报气压两个都用
       千克力/平方厘米 = 工程大气压 at = 98066.5 —— 字面上就是同一个单位
       磅达那类「力/面积」的写法在工程图上比学名更常见，只给学名搜不到

     ★ 毫帕 id 只能用 `mpa2`：`mpa` 早被兆帕占了，而 mPa / MPa 归一化后
       同形（跟毫牛·秒 mns / 兆牛·秒 mns2 是同一类坑）。列表里靠 sym 大小写
       区分，mA 那种歧义在压力里极少见（毫帕只在老气象文献出现）。

     普朗克压强 p_P = c⁷/(ħG²) = 4.6329e113 Pa（G 取 CODATA 2018 的 6.67430e-11）——
     文献里的 4.63309e113 出自更早的 G=6.67408e-11，差在第 5 位有效数字。 */
