  /* ---------- 功率（基准：瓦） ----------
     ★ 这一档的 SI 词头铺满了 24 档（亏瓦 → 昆瓦），所以下面是一条从 1e-30 W
       直排到 1e30 W 的刻度，工程上的老单位按数值插在中间，段内严格升序。
     两种马力不是一回事：公制马力 PS = 735.49875 W（欧洲 / 中国常用），
     英制马力 hp = 745.6998715822702 W（英美常用）。
     ★ 冷吨（制冷量）分**四种写法、三个数值**，别看都叫「冷吨」就混着用：
         美冷吨  2000 lb 冰 / 24 h = 12000 BTU/时 = 3516.85 W（北美空调市场报的就是它）
         英冷吨  2240 lb 冰 / 24 h = 13440 BTU/时 = 3938.47 W（长吨口径，比美制大 12%）
         公制冷吨 1000 kg 冰 / 24 h = 3320 kcal/时 = 3858.58 W（欧洲口径）
         日本冷吨 JIS B 8615 也定 3320 kcal/时，数值与公制完全相同，
                 所以两条并列、同系数 —— 分开列是因为日本设备铭牌上写的就是「冷凍トン」，
                 用户在列表里搜这个词得能搜到。
       三条一律写成「质量 × 熔化热 ÷ 24 h」的算式：英制用 144 BTU/lb，
       公制用 79.68 kcal/kg —— 两个熔化热各有出处，别拿一个去推另一个。
     ★ 锅炉马力 BHP **不是马力**：它是「每小时把 34.5 lb 的水在 212 ℉ 蒸干」
       的热功率，按定义 33475 BTU/时 ≈ 9810.55 W，比英制马力大 13 倍。
     ★ 伏安 VA / 乏 var 与瓦同量纲（视在功率 / 无功功率），有了功率因数才跟 W
       差一个系数 —— 换算器不管功率因数，所以三条按 1:1 收，不是漏了系数。
     ★ 卡/秒、千卡/时、BTU/时、英尺·磅力/秒、尔格/秒 都是「能量表的某个单位 ÷ 秒」，
       值直接引用能量那边的定义（4.184 / 4184 / 1055.05585262 / 1.3558179…），
       不另抄一个近似值。
     ★ 普朗克功率 P_P = c⁵/G = 3.6283e52 W（G 取 CODATA 2018 的 6.6743e-11）。 */
