const UNIT_HOME = 'length';          // 每次进来从哪一类开始

/* ---------- 运行状态 ---------- */
let cvtCat     = UNIT_HOME;              // 当前类别（含子量，如 voltage）
let cvtParent  = '';                     // 当前类别所属的领域键（如 electric）；顶层类别为空串
let cvtSel     = { from: '', to: '' };   // 上下两栏分别选中的单位 id
let cvtPicking = null;                   // 弹窗正为哪一栏开着：'from' | 'to' | null

/* ==========================================================
   二、小工具
   ========================================================== */

/** 当前类别的单位表 */
function cvtUnits() {
  const cat = UNITS[cvtCat];
  return cat ? cat.units : [];
}

/** 按 id 取一个单位（取不到返回 null，调用方自己兜） */
function cvtUnit(id) {
  return cvtUnits().find(u => u.id === id) || null;
}

/** 副输入的权重：Ω^(−a) · A^(−b)。
 *
 *  只有「光学」那一档用得上，指数 a / b 的含义见 UNITS.optics 那段说明。
 *  指数是 0 的那一项在这次换算里用不到，aux 里没给值也照样对
 *  （Math.pow(任意数, 0) 恒为 1）—— 所以「只要立体角」的那些组合
 *  完全不用管面积填没填。 */
function cvtAuxWeight(u, aux) {
  const a = u.a || 0;
  const b = u.b || 0;
  const omega = aux && aux.omega != null ? aux.omega : 1;
  const area  = aux && aux.area  != null ? aux.area  : 1;
  return Math.pow(omega, -a) * Math.pow(area, -b);
}

/** 科学计数法：最多 4 位小数，并去掉尾数后面多余的 0（1.0000e-7 → 1e-7） */
function cvtSci(v) {
  return v.toExponential(4).replace(/\.?0+e/, 'e');
}

/** 换算结果的显示：
 *
 *  · **整数原样印**（见下面那条）：数据存储那两列换算出来全是整数，
 *    用户要的就是那串确切数字，科学计数法反而把位数裁掉了
 *  · **「10 位有效数字」只管小数**：整数已经在上面被接走了，走到这一步的
 *    都不是整数。小数按**有效数字**收尾（10 位），不是按小数位 ——
 *    0.0006213711922 和 1609.344 这种量级差很远的数，用同一个小数位数
 *    是没法兼顾的
 *  · 收完再去掉尾随的 0（100.0000000 → 100），输入框里才干净
 *  · 太大 / 太小的数改用科学计数法，否则「0.000000000001」这种一行全是 0
 */
function cvtFmt(v) {
  if (!Number.isFinite(v)) return '';
  if (v === 0) return '0';

  const a = Math.abs(v);

  /* 整数先兜一道：1 TiB → B 是 1099511627776，写成 1.0995e+12 等于把用户
     想看的那几位裁了；而且下面 toPrecision(10) 那条路还会把 999999999999
     这种 12 位整数舍成 1e+12，更亏。
     上限卡在 2⁵³（Number.isSafeInteger，即 |v| ≤ 2⁵³−1）：double 只保证
     这个范围内的整数一位不差，再往上 Number → String 印出来的末几位是
     假的 —— 2⁶⁰ 会印成 1152921504606847000，而它的真身是
     1152921504606846976。所以超了就老老实实回到科学计数法，绝不印假数字。 */
  if (Number.isSafeInteger(v)) return String(v);

  if (a >= 1e12 || a < 1e-6) return cvtSci(v);

  const s = v.toPrecision(10);
  if (s.indexOf('e') >= 0) return cvtSci(v);      // 兜底：仍被写成指数形式
  return s.indexOf('.') >= 0 ? s.replace(/0+$/, '').replace(/\.$/, '') : s;
}

/** 单个字符的归一 + 放行：
 *    · 全角数字、全角标点、中文句号、各种减号 / 除号 → 半角 ASCII
 *    · 数字 / - / + / . / / / e 各自放行
 *    · 其余一律返回空串（调用方会把它丢掉）
 *
 *  放行表收得很窄，但比原来多了两个字符 —— `e` 和 `+`，为的是科学计数法
 *  （1e+3 这种）。`e` 只认得小写（大写 E、全角 ｅ 都归一成它），
 *  于是 `1E3` 和 `1e3` 是同一个意思，`+` 则只用在指数里
 *  （`+5` 这种写法判读那步会挡下来，见 cvtParsePlain）。
 *  空格、中文、别的字母照样进不来。归一都是一比一，所以改完不影响光标位置。 */
function cvtChar(ch) {
  if (ch >= '\uFF10' && ch <= '\uFF19') {                // ０-９
    return String.fromCharCode(ch.charCodeAt(0) - 0xFEE0);
  }
  if (ch === '\uFF0E' || ch === '\u3002') return '.';    // ．。
  if (ch === '\u2212' || ch === '\uFF0D' ||
      ch === '\u2013' || ch === '\u2014') return '-';    // − － – —
  if (ch === '\u00F7' || ch === '\uFF0F') return '/';    // ÷ ／
  if (ch === '\uFF0B') return '+';                       // ＋
  if (ch === '\uFF45' || ch === '\uFF25' || ch === 'E') return 'e';  // ｅ Ｅ E
  if ('0123456789.-/+e'.indexOf(ch) >= 0) return ch;
  return '';
}

/** 就地过一遍输入框，把放行表之外的字符剔掉。
 *
 *  直接改 value 会把光标顶到末尾，所以要先数出「光标前面被删掉了几个
 *  字符」，再把光标放回原来的位置 —— 否则在中间插一个字，光标就飞到最后。
 *
 *  charMap 可以换成别的一套放行表 —— 副输入框要放行 π，走的就是
 *  cvtAuxChar（见下）。不传就是主输入框那套最窄的表。 */
function cvtFilter(el, charMap) {
  const map = charMap || cvtChar;
  const raw = el.value;
  const caret = typeof el.selectionStart === 'number' ? el.selectionStart : raw.length;
  let out = '';
  let dropped = 0;

  for (let i = 0; i < raw.length; i++) {
    const ch = map(raw.charAt(i));
    if (ch) out += ch;
    else if (i < caret) dropped++;
  }

  if (out === raw) return;
  el.value = out;
  const pos = Math.max(0, Math.min(caret - dropped, out.length));
  try { el.setSelectionRange(pos, pos); } catch (_) {}
}

/** 副输入框的字符表 = 上面那套 + 圆周率 π。
 *
 *  π 只放在**立体角**那一栏用（面积跟圆周率没关系，那栏走的还是 cvtChar）。
 *  软键盘上专门有个「π」键（见下面 cvtPad 那一节），点一下就是这个字符；
 *  从别处粘一行 0.5π 进来，也认。
 *  ∏（U+220F，数学里的连乘号）长得像，顺手也归一成 π —— 粘错了不至于
 *  被静默吃掉，变成一个莫名其妙的结果。 */
function cvtAuxChar(ch) {
  if (ch === '\u03C0' || ch === '\u220F' || ch === '\u1D28') return 'π';
  return cvtChar(ch);
}

/* ==========================================================
   三、判读：整串必须读得出来，且是「自然数 / 0 / 负数 / 小数 / 分数 / 科学计数法」
   ========================================================== */

/** 不带指数的那一层判读。返回 { empty:true }、{ value } 或 { msg }。
 *
 *  认得的形状（正负号可选，且只能在最前面）：
 *      自然数 / 0   12、0
 *      小数         1.5、.5、1.（尾随的小数点当成整数）
 *      分数         a/b，a、b 都是自然数，b ≠ 0；按除法算
 *      负数         上面任意一种前面加 -
 *  其余一律报错：小数点或除号多了、符号不在最前、缺胳膊少腿……
 *  具体报什么在下面逐条给，尽量让用户一眼知道该改哪儿。
 *
 *  科学计数法那层（e±指数）在下面的 cvtParse 里，先摘掉指数再叫这里 ——
 *  于是「尾数怎么读」的规矩只有这一份，两处不会各写一套。 */
function cvtParsePlain(raw) {
  if (!raw) return { empty: true };

  let body = raw;
  let neg = false;
  if (body.charAt(0) === '-') { neg = true; body = body.slice(1); }
  else if (body.charAt(0) === '+') body = body.slice(1);   // 前面多打一个 + 不较真

  if (!body) return { msg: '数字还没写完' };
  if (body === '.') return { msg: '数字还没写完' };

  const parts = body.split('/');
  if (parts.length > 2) return { msg: '除号只能有一个' };

  if (parts.length === 2) {
    const a = parts[0], b = parts[1];
    if (!/^\d+$/.test(a) || !/^\d+$/.test(b)) {
      return { msg: '分数要写成「数字/数字」，例如 3/4' };
    }
    if (Number(b) === 0) return { msg: '分母不能为 0' };
    const v = Number(a) / Number(b);
    return { value: neg ? -v : v };
  }

  if ((body.match(/\./g) || []).length > 1) return { msg: '小数点只能有一个' };
  if (!/^(?:\d+\.?\d*|\.\d+)$/.test(body)) {
    return { msg: '只能填一个数，例如 -3、1.5、3/4' };
  }
  const v = Number(body);
  return { value: neg ? -v : v };
}

/** 判读输入（带科学计数法）。返回 { empty:true }、{ value } 或 { msg }。
 *
 *  在 cvtParsePlain 上面多认一层**科学计数法**，形状是
 *
 *        尾数 e ± 指数
 *
 *      1e+3     → 1000        （键盘上那个「e+」键就是插 "e+"）
 *      1e-9     → 1e-9        （不用 e 的话得写 0.000000001）
 *      1e3      → 1000        （指数前的 ± 可以省）
 *      2.5e+2   → 250
 *      -4e+2    → -400
 *      1.5e-4   → 0.00015
 *
 *  几条刻意的取舍：
 *    · 指数必须是**整数**，不带小数点（1e+2.5 不收）—— 真有这种需求，
 *      尾数上拨一位就行
 *    · 尾数不许是**分数**：`3/4e+2` 到底该读成 (3/4)×100 还是 3/(4×100)？
 *      两种都讲得通，索性两个都不认，让人改写成 0.75e+2
 *    · e 只能有一个，尾数照旧走 cvtParsePlain，所以 12、-3、1.5 都能当尾数
 */
function cvtParse(raw) {
  if (!raw) return { empty: true };

  const eAt = raw.search(/[eE]/);
  if (eAt < 0) return cvtParsePlain(raw);

  const mant = raw.slice(0, eAt);
  let exp = raw.slice(eAt + 1);

  if (exp.search(/[eE]/) >= 0) return { msg: 'e 只能有一个' };
  if (mant.indexOf('/') >= 0) {
    return { msg: '科学计数法不能再带分数，尾数写成小数，例如 0.75e+3' };
  }
  if (!exp) return { msg: 'e 后面还要写指数，例如 1e+3' };

  let sign = 1;
  if (exp.charAt(0) === '+') exp = exp.slice(1);
  else if (exp.charAt(0) === '-') { sign = -1; exp = exp.slice(1); }
  if (!/^\d+$/.test(exp)) return { msg: '指数要写成整数，例如 1e+3、2.5e-4' };

  const m = cvtParsePlain(mant);
  if (m.empty) return { msg: 'e 前面要有一个数，例如 1e+3' };
  if (m.msg) return m;

  // 0e+999 之类：Math.pow 会给 Infinity、0×Infinity 又是 NaN，先把 0 摘出去
  const v = m.value === 0 ? 0 : m.value * Math.pow(10, sign * Number(exp));
  return Number.isFinite(v) ? { value: v } : { msg: '这个数字太大了' };
}

/** 副输入框的判读：cvtParse 那套 + 允许**末尾带一个 π**。
 *
 *    4π   → 4 × π          （点药丸就是把这个串写进框里）
 *    π    → π
 *    0.5π → 0.5 × π
 *    1    → 1
 *
 *  allowPi 为 false 的框（面积）就不认 π —— 面积跟圆周率没关系，
 *  万一写了个 π 出来，直接按 cvtParse 报错，别静默算出一个怪结果。 */
function cvtAuxParse(raw, allowPi) {
  if (!raw) return { empty: true };

  let body = raw;
  let pi = false;
  if (allowPi && body.slice(-1) === 'π') {
    pi = true;
    body = body.slice(0, -1);
  }
  if (!body) return pi ? { value: Math.PI } : { msg: '数字还没写完' };

  const p = cvtParse(body);
  if (p.empty || p.msg) return p;
  return { value: pi ? p.value * Math.PI : p.value };
}

/* ==========================================================
   四、换算：上框 → 下框
   ========================================================== */

/** 把一个值从「上单位」换到「下单位」。
 *
 *  三条路：
 *    · 纯系数（绝大多数类别）：值 × k上 ÷ k下
 *    · 带偏移的类别（温度）：走类别自己的 toBase / fromBase 钩子，
 *      先化成基准值，再从基准值化到目标单位
 *    · 跨量的类别（光学）：同一对钩子，但多传一个 aux
 *      （= 用户填的立体角 / 面积），因为那两个量光靠单位是推不出来的
 */
function cvtConvert(v, aux) {
  const cat = UNITS[cvtCat];
  const f = cvtUnit(cvtSel.from);
  const t = cvtUnit(cvtSel.to);
  if (!f || !t) return null;

  if (cat && typeof cat.toBase === 'function' && typeof cat.fromBase === 'function') {
    return cat.fromBase(cat.toBase(v, f.id, aux), t.id, aux);
  }
  return v * f.k / t.k;
}

/** 上框是唯一输入源，下框只是显示（readonly）。空着不算错，直接清空结果。
 *
 *  顺序上有一点讲究：**先**把副输入那块摆好（显隐 + 清提示），再算数值。
 *  因为副输入块只跟「上下单位」有关，跟主框里填没填没关系 —— 上下单位
 *  一换（互换按钮 / 换单位），这一块该出现该消失都要立刻跟上。 */
function cvtSync() {
  const need = cvtAuxNeed();
  cvtPaintAux(need);
  cvtAuxClearNotes();

  const raw = cvtFrom.value;
  if (!raw) {
    cvtTo.value = '';
    clearError(cvtFrom);
    // 主框空着也要把副输入摆好：用户可能先填几何量、再回来填数值
    cvtDemandAux(need);
    return;
  }

  const p = cvtParse(raw);
  if (p.msg) {
    cvtTo.value = '';
    setError(cvtFrom, p.msg);
    cvtDemandAux(need);
    return;
  }
  // 位数多到 Number 也接不住（几百位数字）——单独说一句，别让它静默变成 Infinity
  if (!Number.isFinite(p.value)) {
    cvtTo.value = '';
    setError(cvtFrom, '这个数字太大了');
    cvtDemandAux(need);
    return;
  }
  clearError(cvtFrom);

  // 副输入：需要但没填 / 填错了，就先不出结果。
  // 没填只给一句灰提示，不标红 —— 刚进这一类时本来就是空的，
  // 一上来就满屏红框太吓人；填了但不对才标红。
  const aux = cvtReadAux(need);
  if (aux.msg) {
    cvtTo.value = '';
    cvtAuxNote(aux);
    return;
  }

  const out = cvtConvert(p.value, aux.values);
  cvtTo.value = out === null ? '' : cvtFmt(out);
}

/* ----------------------------------------------------------
   四之二、副输入框（立体角 / 面积）
   ----------------------------------------------------------
   只有「光学」那一档（UNITS.optics）用得上：那一档的单位跨了四个量，
   光靠单位之间的系数换不过去，还得知道光摊在多宽的立体角、多大一片面积上。

   这一节干三件事：
     cvtAuxNeed    —— 当前这对上下单位，到底缺哪个几何量（现算，不写死）
     cvtPaintAux   —— 按上一步的结果摆显隐、写标签和那句说明
     cvtReadAux    —— 把框里的字读成数（顺带校验），给换算那步用
   其它类别没有 aux 字段：cvtAuxNeed 一律返回"都不要"，整块 hidden，
   行为和一个字没改之前完全一样。
   ---------------------------------------------------------- */

/** 当前这对上下单位，需不需要立体角 / 面积。
 *
 *  判据是**指数差**（指数 a / b 的含义见 UNITS.optics）：
 *    a 不同 → 差着立体角     b 不同 → 差着面积
 *  不用一张 (from,to) 的表逐个列 —— 单位加一个（比如将来补「熙提」）
 *  也照样对。 */
function cvtAuxNeed() {
  const none = { omega: false, area: false };
  const cat = UNITS[cvtCat];
  if (!cat || !cat.aux) return none;

  const f = cvtUnit(cvtSel.from);
  const t = cvtUnit(cvtSel.to);
  if (!f || !t) return none;

  return {
    omega: (f.a || 0) !== (t.a || 0),
    area:  (f.b || 0) !== (t.b || 0),
  };
}

/** 摆副输入块：整体的显隐、每一栏的显隐、标签上的单位、顶头那句说明。
 *
 *  标签和 placeholder 都从数据的 aux 里取 —— 想改文案改 UNITS 那边就行，
 *  不用回来翻这里。（回形针一样的空括号问题在这不存在：
 *  label 自带单位，symbol 有就写、没有就只剩名字。） */
function cvtPaintAux(need) {
  const cat = UNITS[cvtCat];
  const spec = (cat && cat.aux) || null;
  const want = !!(spec && (need.omega || need.area));

  cvtAuxEl.hidden = !want;
  if (!want) return;

  cvtAuxOmegaItem.hidden = !need.omega;
  cvtAuxAreaItem.hidden  = !need.area;

  if (need.omega && spec.omega) {
    cvtAuxOmegaLbl.textContent = spec.omega.label + '（' + spec.omega.unit + '）';
    cvtAuxOmegaEl.placeholder = spec.omega.placeholder || '';
  }
  if (need.area && spec.area) {
    cvtAuxAreaLbl.textContent = spec.area.label + '（' + spec.area.unit + '）';
    cvtAuxAreaEl.placeholder = spec.area.placeholder || '';
  }

  // 说明「这一对单位之间到底差着什么」——不然冒出来一个空框，用户不知道要填啥。
  // 名字取当前的上下单位，跟着换单位一起变。
  const f = cvtUnit(cvtSel.from);
  const t = cvtUnit(cvtSel.to);
  const parts = [];
  if (need.omega) parts.push('立体角');
  if (need.area) parts.push('面积');
  cvtAuxHeadEl.textContent =
    '「' + (f ? f.label : '？') + '」和「' + (t ? t.label : '？') + '」之间还差' +
    parts.join('和') + '，填好才能换算';

  cvtPaintAuxChips();
}

/** 把两个副输入框的提示清干净（红框、灰提示都收掉）。
 *  每次 cvtSync 开头都过一遍，免得上一对单位的报错留在那儿。 */
function cvtAuxClearNotes() {
  [cvtAuxOmegaEl, cvtAuxAreaEl].forEach(el => {
    clearError(el);
    cvtSoftHint(el, '');
  });
}

/** 副输入框的清空（进类别 / 复位时用）。
 *
 *  特意**不**预填。4π 是最常见的那种情形（各向同性光源），但"1 流明等于
 *  多少尼特"没有哪组几何量能算标准答案 —— 先填一个数进去，用户很容易
 *  直接读走那个结果，却没意识到那是我们替他假设的。宁可留空，让他自己
 *  点一下（药丸就是为这一步准备的：4π / 2π / π 各一个，一下就好）。 */
function cvtAuxClearInputs() {
  cvtAuxOmegaEl.value = '';
  cvtAuxAreaEl.value = '';
  cvtAuxClearNotes();
  cvtPaintAuxChips();
}

/** 给输入框挂一句**中性**提示（灰的，不是报错的红）。
 *
 *  core.js 的 .hint 默认是告警色，这里加个 .soft 改回次要文字色 ——
 *  「还没填」是正常状态，不该长成一条错误。 */
function cvtSoftHint(el, msg) {
  const wrap = el.closest('[data-field]');
  const hint = wrap && wrap.nextElementSibling;
  if (!hint || !hint.classList.contains('hint')) return;
  hint.textContent = msg || '';
  hint.classList.toggle('show', !!msg);
  hint.classList.toggle('soft', !!msg);
}

/** 把 cvtReadAux 的结果挂到对应的输入框上。
 *
 *  标红前先摘掉 .soft —— 那句灰提示和红提示共用同一个 .hint（core.js 的
 *  setError 只管 textContent 和 .show，不碰别的类），不摘的话红字会被
 *  上一次的 .soft 压成灰色，看起来像没在报错。 */
function cvtAuxNote(r) {
  if (!r || !r.msg) return;
  const wrap = r.el.closest('[data-field]');
  const hint = wrap && wrap.nextElementSibling;
  if (hint && hint.classList.contains('hint')) hint.classList.remove('soft');

  if (r.hard) setError(r.el, r.msg);
  else cvtSoftHint(r.el, r.msg);
}

/** 读副输入框。返回 { values } 或 { el, msg, hard }。
 *
 *  hard=true  → 填了但不对（标红）
 *  hard=false → 还没填（灰提示）
 *  只读「这一次用得上」的那几个（need 说了算），用不上的连看都不看 ——
 *  所以切换单位时留在框里的旧值不会跑进来作怪。 */
function cvtReadAux(need) {
  const values = {};
  const list = [
    ['omega', need.omega, cvtAuxOmegaEl, true],
    ['area',  need.area,  cvtAuxAreaEl,  false],
  ];

  for (const [key, want, el, allowPi] of list) {
    if (!want) continue;

    if (!el.value) {
      return { el, msg: '填好这一项才能算出结果', hard: false };
    }
    const p = cvtAuxParse(el.value, allowPi);
    if (p.msg) return { el, msg: p.msg, hard: true };
    if (!Number.isFinite(p.value)) return { el, msg: '这个数字太大了', hard: true };
    // 立体角 / 面积都得是正数：0 会让结果爆掉（除以 0），负数则没有物理意义
    if (!(p.value > 0)) {
      return { el, msg: key === 'omega' ? '立体角得大于 0' : '面积得大于 0', hard: true };
    }
    values[key] = p.value;
  }
  return { values };
}

/** 主框空着 / 写错了的时候，也把副输入框的提示摆好。
 *  用户很可能是先填立体角、再回头填数值的，提示不该等他填完数值才出现。 */
function cvtDemandAux(need) {
  cvtAuxNote(cvtReadAux(need));
}

/** 药丸的选中态：框里的字正好等于某个常用值（4π / 2π / π）就点亮它。
 *  用户自己敲了个 12.566 进来的话，三个药丸就都不亮 —— 那也正常。 */
function cvtPaintAuxChips() {
  const cur = cvtAuxOmegaEl.value;
  $$('[data-cvt-omega]', cvtAuxOmegaChips).forEach(chip => {
    chip.setAttribute('aria-checked', String(chip.dataset.cvtOmega === cur));
  });
}

/** 把单位写到按钮上：`米 (m)`，后面跟一个下拉箭头。
 *  没有符号的单位（亩 / 斤 / 天…）就只写名字，不留一对空括号。
 *  体积⇄质量那一层也用这个（三个按钮长一个样）。 */
function cvtPaintUnitBtn(btn, u, label) {
  btn.textContent = u ? (u.sym ? u.label + ' (' + u.sym + ')' : u.label) : '—';

  const arrow = document.createElement('span');
  arrow.className = 'picker-arrow';
  arrow.setAttribute('aria-hidden', 'true');
  btn.appendChild(arrow);

  btn.setAttribute('aria-label', label + '：' + (u ? u.label : '未选择') + '，点击更换');
}

function cvtPaintUnits() {
  [['from', cvtFromBtn, '原单位'], ['to', cvtToBtn, '目标单位']].forEach(([which, btn, label]) => {
    cvtPaintUnitBtn(btn, cvtUnit(cvtSel[which]), label);
  });
}

/* ==========================================================
   五、单位弹窗（药丸）
   ========================================================== */

/** 分组的小标题 + 强制换行。
 *
 *  单位多了以后（体积＆容积这种），所有药丸挤在一起就分不清哪几个是
 *  一伙的 —— 这里在换组的地方插一条占满整行的说明，下一组自然从新行
 *  开始（.chips-full 是 app.css 里已有的"独占一行"盒子，星座那个
 *  弹窗也在用）。 */
function cvtGroupBreak(name) {
  const row = document.createElement('div');
  row.className = 'chips-full chips-group';
  row.textContent = name;
  return row;
}

function cvtRenderChips() {
  const src = cvtPickSource();
  const cur = src.cur;

  /* 两个过滤器，各管各的：
       · 显示设置（全部 / 常用 / 自定义）只作用于**换算页上下两栏**那个弹窗 ——
         桥卡的体积 / 质量 / 密度三张表不走 UNIT_META，也不该被用户藏起来
       · 放大镜里的关键词：范围就是这一档（src.units 本来就是当前量的表），
         跨量搜单位要到外面顶部那条搜索框去 */
  const rng = (cvtPicking === 'from' || cvtPicking === 'to') ? cvtCat : '';
  const q = cvtNorm(unitPickerFindInput.value);

  /* 排序（大小升序 / 降序 / 语义），只在组内动，组的先后不变。
     桥卡那三张表不走 UNITS，rng 是空串 —— 它们只有纯 k 条目，
     照样能按大小排，只是没有组边界可依。 */
  const list = cvtSortUnits(rng, src.units);

  unitPickerChips.textContent = '';
  let lastGroup = null;
  let shown = 0;

  list.forEach(u => {
    if (rng && !cvtVisible(rng, u)) return;
    if (q && cvtUnitScore(q, rng || cvtCat, u) <= 0) return;
    shown++;

    // 换组了：先插一条换行 + 组名。第一组也要标，不然看不出分组是从哪开始的
    if (u.group && u.group !== lastGroup) {
      unitPickerChips.appendChild(cvtGroupBreak(u.group));
      lastGroup = u.group;
    }

    const chip = document.createElement('button');
    chip.type = 'button';
    chip.className = 'chip';
    chip.setAttribute('role', 'radio');
    chip.setAttribute('aria-checked', String(u.id === cur));
    chip.dataset.unit = u.id;
    chip.appendChild(document.createTextNode(u.label));

    // 没有符号的单位这里就不挂 .sym，只留中文名
    if (u.sym) {
      const sym = document.createElement('span');
      sym.className = 'sym';
      sym.textContent = u.sym;
      chip.appendChild(sym);
    }

    unitPickerChips.appendChild(chip);
  });

  /* 一条都没有（搜了个不存在的词）：给一句话，别留一片空白让人以为卡住了 */
  if (unitPickerEmptyEl) unitPickerEmptyEl.hidden = shown > 0;
}

/** 弹窗这次该列哪张单位表、当前选中哪个 —— 换算界面和体积⇄质量共用
 *  同一个药丸弹窗，只有数据源不同，在这里分道。 */
function cvtPickSource() {
  if (cvtPicking === 'bdFrom') return { units: bdUnits('from'), cur: bdSel.from };
  if (cvtPicking === 'bdTo')   return { units: bdUnits('to'),   cur: bdSel.to };
  if (cvtPicking === 'bdRho')  return { units: bdUnits('rho'),  cur: bdSel.rho };
  return { units: cvtUnits(), cur: cvtSel[cvtPicking] };
}

/** 弹窗标题：跨量的那一页得说清是哪一栏（体积 / 质量 / 密度），
 *  换算界面里就是老的「原单位 / 目标单位」。 */
function cvtPickerTitle(which) {
  if (which === 'bdFrom') return '选择' + bdQtyName('from') + '单位';
  if (which === 'bdTo')   return '选择' + bdQtyName('to')   + '单位';
  if (which === 'bdRho')  return '选择密度单位';
  return which === 'from' ? '选择原单位' : '选择目标单位';
}

function cvtOpenPicker(which) {
  cvtPicking = which;
  unitPickerTitle.textContent = cvtPickerTitle(which);
  cvtFindbarOpen(false);          // 每次打开都是收起的（放大镜要自己点）
  cvtRenderChips();
  unitPicker.classList.add('show');
}

function cvtClosePicker() {
  unitPicker.classList.remove('show');
  cvtPicking = null;
  cvtFindbarOpen(false);
}

/* ==========================================================
   六、视图切换
   ========================================================== */

/* 两层列表各自的滚动位置。进出时记一下、还回去 —— 类别页和「选量」页
   都可能很长，每次退回来被弹回顶部很难受。
   ★ 只在**那一层当前可见**时才记，否则会把换算页的 scrollTop 误记进去。 */
let cvtCatsScroll = 0;      // 第一层：选领域
let cvtKidsScroll = 0;      // 第二层：一个领域里选量

/** 顶栏标题。子量拼成「电学-电容」，顶层类别就是它自己的名字。
 *  连字符是用户指定的写法（不是「/」也不是「·」），别改。 */
function cvtCatTitle(id) {
  const cat = UNITS[id];
  if (!cat) return '单位换算';
  const p = cat.parent ? UNITS[cat.parent] : null;
  return p ? p.name + '-' + cat.name : cat.name;
}

/** 回到第一层「选领域」 */
function cvtShowCats() {
  cvtClosePicker();
  cvtPadHide();                 // 键盘是给数值框用的，回列表就没它的事了
  cvtGuideHide();
  cvtResetSearchBox();          // 搜索框跟着回列表一起清空（不能留着上一次的词）
  cvtHideViews();               // 七块视图一次全收，下面只打开自己那一块
  unitCatsEl.hidden = false;
  cvtParent = '';
  unitTitleEl.textContent = '单位换算';
  cvtSyncTopbar();

  // 把类别列表滚回进子页面之前的位置。
  // 必须**先**把列表显示出来再设 scrollTop：列表还藏着的时候内容高度是 0，
  // 设进去的值会被浏览器直接夹成 0，等于没还原。
  unitBodyEl.scrollTop = cvtCatsScroll;
}

/** 类别自己的注释（UNITS[cat].note，可选）。
 *  没有这条的类别就把整块收起来 —— 不留一块空的灰底。 */
function cvtPaintCatNote(cat) {
  if (!cvtCatNoteEl) return;
  const text = (cat && cat.note) || '';
  cvtCatNoteEl.textContent = text;
  cvtCatNoteEl.hidden = !text;
}

/** 体积 / 质量这两档下面那颗「换到另一个量去」的跳转。
 *
 *  只在这两档出现（别的类别跟质量、体积没关系，摆出来是噪音）；
 *  文案跟着类别走：体积页上是「体积 → 质量」，质量页上反过来。
 *  点它时会把**当前敲的数和单位一起带过去**（见事件绑定那一段），
 *  用户在体积页算到一半想接着算重量，不用回去重敲一遍。
 *  没有这一档就整块 hidden —— 不留一条空白的框。 */
function cvtPaintBridgeLink(catId) {
  if (!cvtBridgeBtn) return;

  const dir = catId === 'volume' ? 'v2m' : catId === 'mass' ? 'm2v' : '';
  cvtBridgeBtn.hidden = !dir;
  if (!dir) { cvtBridgeBtn.dataset.dir = ''; return; }

  cvtBridgeBtn.dataset.dir = dir;
  cvtBridgeNameEl.textContent = dir === 'v2m' ? '体积 → 质量' : '质量 → 体积';
}

/** 渲染一个领域下的「量」卡片（第二层）。
 *
 *  卡片是**现画**的，不像第一层那样写在 index.html 里：量名和顺序都在
 *  UNITS 的 kids 名单里，抄一份到 HTML 等于同一件事写两处，加一个量要
 *  改两个文件。第一层之所以留在 HTML，是因为那 25 张卡各有自己的 SVG 图标。
 *
 *  图标块里放的是该量的主单位符号（V / Ω / Wb / mol/L…），不是图形 ——
 *  21 个量各画一张图标不值当，符号反而认得更快。4 个字符以上的降一档字号。
 *  ⚠ 这段是 innerHTML 拼的，glyph / name 全部来自本文件的常量，没有用户输入。 */
function cvtRenderKids(parentId) {
  const p = UNITS[parentId];
  if (!p || !p.kids) return;

  unitSubsEl.innerHTML = p.kids.map(id => {
    const k = UNITS[id];
    if (!k) return '';
    const g = k.glyph || '';
    // 字号按符号长度分档（20 / 16 / 12.5px，见 css 的 .unit-kid-sym）
    const cls = g.length >= 4 ? ' is-long' : g.length === 3 ? ' is-mid' : '';
    return '<button type="button" class="tool-btn unit-cat" data-unit-kid="' + id + '">'
         +   '<span class="tool-btn-ico unit-kid-sym' + cls + '" aria-hidden="true">' + g + '</span>'
         +   '<span class="tool-btn-text"><span class="tool-btn-name">' + k.name + '</span></span>'
         +   '<span class="tool-btn-go" aria-hidden="true">'
         +     '<svg viewBox="0 0 24 24" fill="none" stroke-width="2.2" stroke-linecap="round"'
         +          ' stroke-linejoin="round"><path d="M9 5l7 7-7 7" /></svg>'
         +   '</span>'
         + '</button>';
  }).join('');
}

/** 进第二层：某个领域下的量列表。
 *
 *  restore，true = 从换算页退回来的（要还原上次滚到哪儿）；
 *  从类别页点进来是"新开一页"，一律从顶部开始。 */
function cvtShowKids(parentId, restore) {
  const p = UNITS[parentId];
  if (!p) return;
  if (!p.kids) { cvtOpenCat(parentId); return; }   // 没子量的类别不该走到这儿，兜一下

  // 只有从类别页点进来才记类别页的位置（从换算页退回时记的是换算页的，会污染）
  if (restore !== true) cvtCatsScroll = unitBodyEl.scrollTop;
  cvtParent = parentId;

  cvtRenderKids(parentId);
  cvtClosePicker();
  cvtPadHide();
  cvtGuideHide();
  cvtResetSearchBox();

  cvtHideViews();
  unitSubsEl.hidden = false;
  unitTitleEl.textContent = p.name;
  cvtSyncTopbar();

  // ★ 先让它显示出来再设 scrollTop：藏着的时候内容高度是 0，会被夹成 0
  unitBodyEl.scrollTop = restore === true ? cvtKidsScroll : 0;
}

/** 退一层 —— 顶栏返回、Esc、系统返回键三处共用这一份判断，免得三处走岔。
 *  返回 true 表示"这一下被页面吃掉了"；false 表示已经在第一层，
 *  该交给 tools.js 去关整个功能页。 */
function cvtBackOne() {
  if (!cvtResultsEl.hidden) { cvtCloseSearch(); return true; }   // 搜索结果 → 原来的列表
  if (!unitSelfEl.hidden) {                                      // 自定义页：按层退
    if (cvtSelfBack()) return true;                              // 单位 / 量 → 上一层
    cvtShowSettings();                                           // 领域列表 → 设置页
    return true;
  }
  if (!unitSettingsEl.hidden) { cvtShowCats(); return true; }     // 设置页 → 类别页
  if (!unitBridgeEl.hidden) { bdBack(); return true; }            // 体积⇄质量 → 换算页
  if (!unitConvEl.hidden) {                                       // 换算页 → 上一层列表
    if (cvtParent) cvtShowKids(cvtParent, true); else cvtShowCats();
    return true;
  }
  if (!unitSubsEl.hidden) { cvtShowCats(); return true; }         // 选量 → 类别页
  return false;                                                   // 已经在类别页
}

/** 进某个类别的换算界面。
 *  pickFrom / pickTo：从搜索结果点进来时，把刚选中的那一条带过来
 *  （不传就是这一档的默认 from / to，和以前的入口一模一样）。 */
function cvtOpenCat(id, pickFrom, pickTo) {
  const cat = UNITS[id];
  if (!cat) return;
  if (cat.kids) { cvtShowKids(id); return; }    // 父领域：先进选量层，别当普通类别打开

  // 记下当前滚到哪儿了：退回来时还要回到这儿（列表挺长，
  // 每次退出来都被弹回顶部很难受）。哪一层可见就记哪一层。
  if (!unitSubsEl.hidden) cvtKidsScroll = unitBodyEl.scrollTop;
  else cvtCatsScroll = unitBodyEl.scrollTop;

  const ids = cat.units.map(u => u.id);
  /* 可见集：显示设置把某几个单位藏了以后，默认的 from / to 有可能正在其中
     （比如把「厘米」关了，而这档的 to 就是厘米）。这时按钮上会写着一个
     弹窗里根本找不到的单位 —— 用户没法换回来，也算不出东西。
     所以进换算页时先落到可见集里；全被关光（不该发生）才退回全表。 */
  const visIds = cat.units.filter(u => cvtVisible(id, u)).map(u => u.id);
  const pool = visIds.length >= 2 ? visIds : ids;

  const fromFixed = ids.indexOf(pickFrom) >= 0;
  const toFixed   = ids.indexOf(pickTo) >= 0;

  cvtCat = id;
  cvtParent = cat.parent || '';
  cvtSel = {
    from: fromFixed ? pickFrom : cat.from,
    to:   toFixed   ? pickTo   : cat.to,
  };

  /* 只校验**没被指定**的那一栏：用户从搜索里明确点了某一条（哪怕它被
     显示设置藏着），那一条必须留着照用 —— 搜索本来就是全库的。
     回退顺序：这一档的默认单位 → 可见集里第一个常用单位 → 可见集第一个。
     ★ 不能简单地取「可见集第一个」：长度表的第一个是普朗克长度，
       把厘米关掉以后一进页面变成「1 米 = 6.19e34 普朗克长度」。 */
  if (!fromFixed && pool.indexOf(cvtSel.from) < 0) {
    cvtSel.from = cvtFallbackUnit(id, cat.from, cvtSel.to);
  }
  if (!toFixed && pool.indexOf(cvtSel.to) < 0) {
    cvtSel.to = cvtFallbackUnit(id, cat.to, cvtSel.from);
  }

  /* 两栏不能撞成同一个单位 —— 撞了换算结果永远等于原值，看着像坏了。
     撞上时改**没被指定**的那一栏（用户点的是哪一栏，就保哪一栏）。 */
  if (cvtSel.from === cvtSel.to) {
    const alt = pool.find(x => x !== cvtSel.from) || ids.find(x => x !== cvtSel.from);
    if (alt) { if (toFixed) cvtSel.from = alt; else cvtSel.to = alt; }
  }

  // 给个 1：一进来就能看到一条换算结果，不用先自己敲一个数
  cvtFrom.value = '1';
  clearError(cvtFrom);
  cvtAuxClearInputs();                         // 副输入框一律从空白进（不预填，见下）
  cvtPaintUnits();
  cvtPaintCatNote(cat);
  cvtPaintBridgeLink(id);
  cvtSync();

  cvtHideViews();
  unitConvEl.hidden = false;
  unitTitleEl.textContent = cvtCatTitle(id);   // 子量显示成「电学-电容」
  cvtSyncTopbar();
  unitBodyEl.scrollTop = 0;                    // 子页面自己从顶部开始

  /* 这里**不**自动聚焦。以前电脑上会顺手 focus + select（把示例那个 1
     整段选上，敲第一个键就替换掉），但副作用是：一进类别软键盘（.gfx-pad）
     就自己弹出来 —— 用户还没想打字，屏幕先被键盘占掉一截。现在进类别就是
     干干净净一张卡，等用户点了数值框，键盘再出来（focus → cvtPadShow）。
     手机上本来也不聚焦（会弹起系统键盘，挡掉半屏），这一改两边一致。 */
}

/** 复位到初始状态：默认类别、默认单位、数值 1，并停在「选类别」的顶部 */
function cvtReset() {
  cvtCat = UNIT_HOME;
  const cat = UNITS[cvtCat];
  cvtSel = { from: cat.from, to: cat.to };

  cvtFrom.value = '1';
  clearError(cvtFrom);
  cvtAuxClearInputs();
  cvtPaintUnits();
  cvtPaintCatNote(cat);
  cvtSync();

  cvtCatsScroll = 0;      // 重新进来 = 从头看，不沿用上一次的滚动位置
  cvtShowCats();
}

/* ==========================================================
   七、复制（数值 / 结果各一颗）
   ----------------------------------------------------------
   位置：字段头上（.cvt-head 里、label 的右边），也就是下面那颗单位
   按钮的**正上方** —— 一眼看得出它管的是哪一栏，不会跟单位按钮混。
   按钮外观见 css/tools.css 的 .cvt-copy。

   复制的是框里的**原文**：不拼单位、不加等号。用户想拿去用的时候，
   「100 厘米」自己拼一下就有了；反过来，原文要是被拼过就还原不回去。

   两栏共用同一个函数，靠传进来的输入框和名字区分是哪一栏。
   做法、提示语、兜底整套都跟「罗马数字」那页一致（见 js/roman.js
   的四、复制）—— 同一颗按钮，换个页面不该变成另一套手感。
   ========================================================== */

/** 复制提示共用的 key（见 core.js 的 toast 第 4 个参数）：
 *  传了 key 就**同一时刻只留一条**，新的来之前先把旧的那条收掉。
 *
 *  这里必须收：「复制」是最容易被连点的动作 —— 数值点一下、结果点一下，
 *  或者空框点一次报错、填上数再点一次成功。不收的话屏幕上就是两条几乎
 *  一样的气泡叠在一起。三处提示（空内容 / 已复制 / 复制失败）共用同一个
 *  key，所以「先报错、后成功」也只会看到最后那条。
 *  想要回旧的各弹各的，把这个参数去掉即可。 */
const CVT_TOAST_COPY = 'cvt-copy';

/** execCommand 那条老路。剪贴板 API 只在**安全上下文**里给用
 *  （https / localhost 算，局域网 IP 走 http 就不算），
 *  而本站经常是局域网里用 IP 打开的 —— 所以兜底这条路必须留着。 */
function cvtCopyFallback(text) {
  const ta = document.createElement('textarea');
  ta.value = text;
  ta.setAttribute('readonly', '');
  // 放在视口里、但挪到看不见的地方：display:none 的节点选不中
  ta.style.cssText = 'position:fixed;top:0;left:-9999px;opacity:0';
  document.body.appendChild(ta);
  ta.select();
  let ok = false;
  try { ok = document.execCommand('copy'); } catch (_) { ok = false; }
  ta.remove();
  if (!ok) throw new Error('copy failed');
}

/** 复制某一栏的内容。两栏共用，靠传进来的输入框和名字区分。 */
async function cvtCopy(input, label) {
  const text = input.value;
  if (!text) {
    // 上框空着 = 还没填数；下框空着 = 上面还没填对，两句话说清楚
    toast('err', '还没有内容可以复制', label === '结果' ? '先在上面填一个数' : '', CVT_TOAST_COPY);
    return;
  }

  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
    } else {
      cvtCopyFallback(text);
    }
    // 长串截一下再当说明，别把整个提示撑开
    toast('ok', '已复制' + label, text.length > 24 ? text.slice(0, 24) + '…' : text, CVT_TOAST_COPY);
  } catch (_) {
    // 兜底也失败（权限被拒 / 老浏览器）：把话说清楚，让用户自己选中
    toast('err', '复制失败', '请手动选中后复制', CVT_TOAST_COPY);
  }
}

/* ==========================================================
   八、交换上下单位（数字跟着一起换位置）
   ========================================================== */
function cvtSwap() {
  const oldFrom = cvtSel.from;
  cvtSel.from = cvtSel.to;
  cvtSel.to = oldFrom;
  cvtPaintUnits();

  // 数字一起换位：原来在下框的结果挪到上框，再按新单位往下算一遍。
  // 这样「1 米 = 100 厘米」一交换就成了「100 厘米 = 1 米」——同一个长度，
  // 只是换个方向读。上框空着或写错了（下框也是空的）就只换单位。
  const moved = cvtTo.value;
  if (moved) cvtFrom.value = moved;

  cvtSync();

  if (typeof Device !== 'undefined' && Device.isPC()) cvtFrom.focus();
}

/* ==========================================================
   九、软键盘
   ----------------------------------------------------------
   键位是从「罗马数字」那个**数字盘**搬来的（见 js/roman.js）：外观、
   交互、甚至"拦掉 mousedown 保住输入框焦点"那一手都照抄，只改键面：

     数字盘（罗马那页）        这一页
       7 8 9                    e+   e-   /   π
       4 5 6                    7    8    9
       1 2 3                    4    5    6
       切换 0 退格              1    2    3
                                .    0    退格

   · 去掉「切换」—— 这一页只有一套键位，没什么可切的
   · 补上小数点、负号、除号、科学计数法的 e+ / e-、圆周率 π
   · **顶上那行 5 个键**（e+ e- / - π），底下四行是标准的 3 列数字盘。
     这么排是为了不把键盘撑高：总共还是 5 行，和原来一样。
     靠 css 的 .gfx-pad-keys.is-numpad 撑开（15 列网格，顶行每键占 3 格、
     下面每键占 5 格），见 css/tools.css。

   ★ 一个键盘伺候**三个输入框**（数值 / 立体角 / 面积）：谁拿到焦点就
     往谁里面插字（cvtPadTarget）。这一档是这么来的 —— 光学那类要同时填
     数值和几何量，而手机上让系统键盘弹三回是没法用的。

   ★ 「π」是唯一一个**会灰掉**的键：只有立体角那个框认得 π
     （面积和数值都跟圆周率没关系）。光标在别的框上时它置灰 ——
     按下去没反应比看得见的"用不上"更让人犯嘀咕。

   ★ 键位写成下面的数组，加减键都在这一处改。fn:1 是蓝调（功能键），
     op:1 是"排在顶上那行"。 */
const CVT_PAD_KEYS = [
  { l: 'e+', fn: 1, op: 1, ins: 'e+', title: '正的指数，例如 1e+3' },
  { l: 'e-', fn: 1, op: 1, ins: 'e-', title: '负的指数，例如 1e-4' },
  { l: '/',  fn: 1, op: 1,           title: '除号（写分数），例如 3/4' },
  { l: '-',  fn: 1, op: 1, ins: '-', title: '负号，只能写在数的最前面，例如 -5' },
  { l: 'π',  fn: 1, op: 1, title: '圆周率，只在「立体角」里用得上', needsPi: true },

  '7', '8', '9',
  '4', '5', '6',
  '1', '2', '3',

  { l: '.', fn: 1, title: '小数点', ins: '.' },
  '0',
  { act: 'back' },
];

let cvtPadTarget = null;     // 现在这个键盘在给哪个输入框打字
let cvtPadCaret  = 0;        // 那个框里的光标位置

/** 某个输入框用哪套字符表 —— 和它 input 事件里 cvtFilter 传的那套必须一致，
 *  否则键盘插进去的字会被自己的过滤器吃掉（π 就是这么个例子）。 */
function cvtPadCharFor(el) {
  return el === cvtAuxOmegaEl ? cvtAuxChar : cvtChar;
}

/** 造一个键。拦 mousedown 是照抄 roman.js 的做法：不拦的话点一下
 *  输入框就失焦，键盘会跟着收起来，字也就插不进去了。 */
function cvtPadKey(label, opts) {
  const o = opts || {};
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'gfx-key' + (o.fn ? ' is-fn' : '');
  b.textContent = label;
  b.title = o.title || label;
  b.setAttribute('aria-label', o.title || label);

  b.addEventListener('mousedown', e => e.preventDefault());
  b.addEventListener('click', o.action);
  return b;
}

function cvtPadRender() {
  if (!cvtPadKeys || !cvtPadTarget) return;

  const map = cvtPadCharFor(cvtPadTarget);
  cvtPadKeys.textContent = '';

  CVT_PAD_KEYS.forEach(k => {
    if (typeof k === 'string') {
      cvtPadKeys.appendChild(cvtPadKey(k, { action: () => cvtPadInsert(k) }));
      return;
    }
    if (k.act === 'back') {
      cvtPadKeys.appendChild(cvtPadKey('退格', { fn: 1, title: '退格', action: cvtPadBackspace }));
      return;
    }

    const btn = cvtPadKey(k.l, {
      fn: k.fn, title: k.title,
      action: () => cvtPadInsert(k.ins || k.l),
    });
    // 顶上那行（e+ e- / - π）：换一套列宽，见 .is-numpad
    if (k.op) btn.classList.add('is-op');

    // 这个框不认这个字符（只有 π 会撞上）：置灰 + 说明
    if (k.needsPi && map('π') !== 'π') {
      btn.disabled = true;
      btn.title = 'π 只在「立体角」里用得上';
      btn.setAttribute('aria-label', btn.title);
    }
    cvtPadKeys.appendChild(btn);
  });
}

/** 当前框里选中的区间 [start, end)。没选中就是光标处的一个空区间。
 *
 *  得认区间不能只认光标：用户（鼠标拖或键盘 Shift）选了半截数时，
 *  敲键盘上任何一个键都该**替换**掉选中的那一截 —— 只按 selectionStart
 *  插字的话，会在选区前面挤出一段重复的数字，用户还得回头退格。 */
function cvtPadRange(el) {
  const len = el.value.length;
  let s = cvtPadCaret, e = cvtPadCaret;
  if (typeof el.selectionStart === 'number' && typeof el.selectionEnd === 'number') {
    s = Math.min(el.selectionStart, el.selectionEnd);
    e = Math.max(el.selectionStart, el.selectionEnd);
  }
  s = Math.max(0, Math.min(s, len));
  e = Math.max(s, Math.min(e, len));
  return [s, e];
}

/** 往当前框里插一段字。插完把焦点和光标补回原处，再**派发一个 input 事件**
 *  —— 过滤 / 校验 / 重算全交给上面已有的那条链路，这里不另写一套。 */
function cvtPadInsert(text) {
  const el = cvtPadTarget;
  if (!el) return;

  const [s, e] = cvtPadRange(el);
  el.value = el.value.slice(0, s) + text + el.value.slice(e);
  cvtPadCaret = s + text.length;

  cvtPadFocus(el);
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

function cvtPadBackspace() {
  const el = cvtPadTarget;
  if (!el) return;

  let [s, e] = cvtPadRange(el);
  if (s === e) {                   // 没选中就退一格
    if (s <= 0) return;
    s -= 1;
  }

  el.value = el.value.slice(0, s) + el.value.slice(e);
  cvtPadCaret = s;

  cvtPadFocus(el);
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

/** 清空当前框（结果跟着空 —— 它本来就是输入算出来的） */
function cvtPadClear() {
  const el = cvtPadTarget;
  if (!el) return;

  el.value = '';
  cvtPadCaret = 0;
  cvtPadFocus(el);
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

/** 把焦点和光标安回输入框里。preventScroll 很重要 —— 不然每按一个键
 *  浏览器都要把输入框滚进视口，而键盘自己就顶着屏幕底边。 */
function cvtPadFocus(el) {
  try { el.focus({ preventScroll: true }); } catch (_) { try { el.focus(); } catch (__) {} }
  try { el.setSelectionRange(cvtPadCaret, cvtPadCaret); } catch (_) {}
}

function cvtPadShow(el) {
  if (!cvtPad || !el) return;
  cvtPadTarget = el;
  cvtPadCaret = typeof el.selectionStart === 'number' ? el.selectionStart : el.value.length;
  cvtPadRender();
  cvtPad.hidden = false;
  gfxPadEnsureVisible(el, cvtPad);
}

function cvtPadHide() {
  if (cvtPad) cvtPad.hidden = true;
  // 清掉 gfxPadEnsureVisible 给滚动容器补的底边距（和 gfxClearPadScroller 一个意思）
  gfxClearPadScroller();
}

/** 把这一页所有数值框都接到这个键盘上
 *  （换算界面的数值 + 立体角 + 面积，体积⇄质量的体积/质量 + 密度） */
function cvtPadBind() {
  const inputs = [cvtFrom, cvtAuxOmegaEl, cvtAuxAreaEl, bdFromEl, bdDensityEl];

  // 触摸设备：不叫出系统键盘。本站的输入都自带键盘，系统键盘只会挡掉半屏 ——
  // 而且这块键盘是"一个顶三个"的，让系统键盘插进来反而更乱。
  if (typeof Device !== 'undefined' && !Device.isPC()) {
    inputs.forEach(el => el.setAttribute('inputmode', 'none'));
  }

  inputs.forEach(el => {
    el.addEventListener('focus', () => cvtPadShow(el));

    // 兜底：个别浏览器 / 输入法下点一下未必派发 focus，点完再确认一次
    el.addEventListener('click', () => {
      if (cvtPad && cvtPad.hidden) cvtPadShow(el);
      if (typeof el.selectionStart === 'number') cvtPadCaret = el.selectionStart;
    });

    // 失焦时**不要立刻收**：点键盘上的按钮也会让输入框先 blur 一下。
    // 等一个 tick，看焦点是不是落在键盘上、或者挪到了另一个输入框 ——
    // 是就留着（换框时键盘不该闪一下）。
    el.addEventListener('blur', () => {
      setTimeout(() => {
        if (cvtPad && cvtPad.contains(document.activeElement)) return;
        if (inputs.indexOf(document.activeElement) >= 0) return;
        cvtPadHide();
      }, 0);
    });

    ['keyup', 'input', 'select'].forEach(ev => {
      el.addEventListener(ev, () => {
        if (typeof el.selectionStart === 'number') cvtPadCaret = el.selectionStart;
      });
    });
  });
}

/* ---- 键盘头部的两颗按钮 ---- */
if (cvtPad) {
  $('#cvtPadClear').addEventListener('click', cvtPadClear);

  // 「完成」只收键盘，值留着 —— 想接着改了，点一下输入框又出来
  $('#cvtPadDone').addEventListener('click', () => {
    cvtPadHide();
    if (cvtPadTarget) cvtPadTarget.blur();
  });
}

/* ==========================================================
   九之二、体积 ⇄ 质量（密度作桥）
   ----------------------------------------------------------
   质量 = 体积 × 密度。这个式子两头是**两个不同的量**，所以它不属于任何
   一张单位表 —— 单独一层视图。入口只有一处：体积 / 质量换算页底下的
   虚线跳转（见 cvtPaintBridgeLink），进来时带着那边的数值和单位，
   返回时也回到那张换算页。（不放进类别列表 —— 那不是一类单位。）

   状态只有三样：
     bdDir    方向：'v2m'（体积 → 质量）| 'm2v'
     bdSel    { from, to, rho } 三个单位 id（from/to 的含义跟着方向走）
     两个框里的数值就地读，不另存

   换算走三个基准：体积 升、质量 千克、密度 千克/立方米。
     v2m   V(L) → V/1000 (m³) × ρ(kg/m³) → kg → 目标质量单位
     m2v   m(kg) ÷ ρ(kg/m³) → m³ × 1000 → L → 目标体积单位
   密度那档的非线性刻度（API / 波美 / 柏拉图…）不用管：读数和 kg/m³
   之间的来回全借 UNITS.density 的 toBase，这里只管乘除。

   ★ 方向不是"算两遍"：进哪张卡就按哪个方向摆（上栏是体积还是质量），
     中间那颗互换按钮掉头时，上下单位一起换位、结果挪到上面 ——
     和换算界面那颗互换按钮一个手感。
   ========================================================== */

let bdDir = 'v2m';
let bdSel = { from: 'l', to: 'kg', rho: 'gcm3' };
let bdConvScroll = 0;      // 跳走之前换算页滚到哪儿了（返回时还原）

/* 密度快捷键：一组"实心料"、一组"水"，按体积那一栏用的是什么单位二选一。
   ★ 数值全部取**常温 20 ℃**（温度一变密度就变，水最明显）：
       水    998.2071 kg/m³ = 0.9982 g/cm³   （4 ℃ 那个 1.000 是教科书整数）
       纯铁  7.874 g/cm³
       纯银  10.49 g/cm³
       纯金  19.32 g/cm³
   点一颗 = 把密度框填上这个数、把密度单位切到 g/cm³（这几组数就是按它写的）。 */
const BD_RHO_PRESETS = {
  water:  { val: '0.9982' },
  iron:   { val: '7.874'  },
  silver: { val: '10.49'  },
  gold:   { val: '19.32'  },
};

/** 这一层某一栏是哪个量：'体积' | '质量'（方向反了，答案就反） */
function bdQtyName(which) {
  const isVol = bdDir === 'v2m' ? which === 'from' : which === 'to';
  return isVol ? '体积' : '质量';
}

/** 某一栏能选哪些单位 —— 密度那栏直接借密度档整张表（含比重刻度） */
function bdUnits(which) {
  if (which === 'rho') return UNITS.density.units;
  return bdQtyName(which) === '体积' ? UNITS.volume.units : UNITS.mass.units;
}

function bdUnit(which, id) {
  return bdUnits(which).find(u => u.id === id) || null;
}

/** 三个单位按钮 + 两栏标签 + 顶栏标题 + 那句公式，全跟着方向刷 */
function bdPaintUnits() {
  const fromIsVol = bdQtyName('from') === '体积';

  bdFromLabelEl.textContent = fromIsVol ? '体积 V' : '质量 m';
  bdToLabelEl.textContent   = fromIsVol ? '质量 m' : '体积 V';
  bdRhoHeadEl.textContent   = fromIsVol ? '质量 = 体积 × 密度' : '体积 = 质量 ÷ 密度';

  cvtPaintUnitBtn(bdFromUnitBtn,  bdUnit('from', bdSel.from),  bdQtyName('from') + '单位');
  cvtPaintUnitBtn(bdToUnitBtn,    bdUnit('to',   bdSel.to),    bdQtyName('to')   + '单位');
  cvtPaintUnitBtn(bdDensityBtn,   bdUnit('rho',  bdSel.rho),   '密度单位');

  unitTitleEl.textContent = bdQtyName('from') + ' → ' + bdQtyName('to');

  bdPaintRhoChips();

  /* 底下那句举例跟着方向换 —— 反过来读的时候，"同样 1 升"就不对味了：
     质量→体积问的是"这么多斤两占多大地方"。 */
  bdNoteEl.textContent = fromIsVol
    ? '密度决定结果：同样 1 升，水约 1 千克、汽油约 0.74 千克、铁约 7.87 千克（快捷键按常温 20 ℃）'
    : '密度决定结果：同样 1 千克，水约 1 升、汽油约 1.35 升、铁约 0.13 升（快捷键按常温 20 ℃）';
}

/** 清掉某栏的提示（红字和灰字一起收） */
function bdClearHint(el) {
  cvtSoftHint(el, '');      // 顺手摘掉 .soft，不然下次的红字会被压成灰的
  clearError(el);
}

/** 摆提示：soft=true 是"还没填"的灰字，false 是"填错了"的红字 */
function bdHint(el, msg, soft) {
  if (soft) { cvtSoftHint(el, msg); return; }
  cvtSoftHint(el, '');          // 先摘掉 .soft，不然这句红字会被压成灰的
  setError(el, msg);
}

/** 读密度那一栏 → { value: kg/m³ } 或 { msg, hard }。
 *  hard=false 只表示"还没填"（灰提示），不是错。
 *  非线性刻度由 UNITS.density.toBase 负责，这里只兜"换出来不是正数"的读数
 *  （比如重波美 145 度 = 比重无穷大，那是这个读数本身没有对应的密度）。 */
function bdReadDensity() {
  const raw = bdDensityEl.value;
  if (!raw) return { msg: '填一个密度才能换算', hard: false };

  const p = cvtParse(raw);
  if (p.msg) return { msg: p.msg, hard: true };
  if (!Number.isFinite(p.value)) return { msg: '这个数字太大了', hard: true };

  const rho = UNITS.density.toBase(p.value, bdSel.rho);
  if (!Number.isFinite(rho) || !(rho > 0)) {
    return { msg: '这个读数换不出正的密度，换一个试试', hard: true };
  }
  return { value: rho };
}

/** 上框 → 下框。空着不算错，只是没结果；密度缺了就先讨密度。 */
function bdSync() {
  // 1) 上面的数
  let v = null;
  if (bdFromEl.value) {
    const p = cvtParse(bdFromEl.value);
    if (p.msg) {
      bdToEl.value = '';
      setError(bdFromEl, p.msg);
      bdPaintRhoHint();          // 密度那句提示照摆，别让用户以为只要填上面
      return;
    }
    if (!Number.isFinite(p.value)) {
      bdToEl.value = '';
      setError(bdFromEl, '这个数字太大了');
      return;
    }
    v = p.value;
  }
  clearError(bdFromEl);

  // 2) 桥：密度
  const rho = bdReadDensity();
  if (rho.msg) {
    bdToEl.value = '';
    bdHint(bdDensityEl, rho.msg, !rho.hard);
    return;
  }
  bdClearHint(bdDensityEl);

  // 3) 上面空着就先不算（密度填好了也不出假结果）
  if (v === null) { bdToEl.value = ''; return; }

  const fromU = bdUnit('from', bdSel.from);
  const toU   = bdUnit('to',   bdSel.to);
  if (!fromU || !toU) { bdToEl.value = ''; return; }

  let res;
  if (bdDir === 'v2m') {
    const litres = v * fromU.k;              // → 升（体积的基准）
    const kg = litres / 1000 * rho.value;    // 升 → 立方米 → 千克
    res = kg / toU.k;                        // 千克 → 目标质量单位
  } else {
    const kg = v * fromU.k;                  // → 千克（质量的基准）
    const litres = kg / rho.value * 1000;    // 千克 → 立方米 → 升
    res = litres / toU.k;                    // 升 → 目标体积单位
  }
  bdToEl.value = cvtFmt(res);
}

/** 密度快捷键摆哪一组：看**体积那一栏**用的是立方单位，还是升/加仑这类容积单位。
 *    体积（cm³、m³…）→ 纯铁 / 纯银 / 纯金：量一块料有多重
 *    容积（L、mL、加仑…）→ 水：量一壶水有多重
 *  另一组整排 hidden（CSS 里补了 .chip[hidden]{display:none}，
 *  因为 .chip 自带 display:inline-flex，会压掉浏览器的 [hidden]）。 */
function bdPaintRhoChips() {
  if (!bdRhoChipsEl) return;

  const volWhich = bdQtyName('from') === '体积' ? 'from' : 'to';
  const volU = bdUnit(volWhich, bdSel[volWhich]);
  const isCap = !!volU && volU.group === '容积';

  // 亮哪一颗：密度单位正好是 g/cm³、框里的字也正好等于那个数
  const cur = bdDensityEl.value.trim();
  const inGcm3 = bdSel.rho === 'gcm3';

  $$('[data-bd-rho]', bdRhoChipsEl).forEach(chip => {
    const isWater = chip.dataset.bdRho === 'water';
    chip.hidden = isCap ? !isWater : isWater;
    const p = BD_RHO_PRESETS[chip.dataset.bdRho];
    chip.setAttribute('aria-checked', String(inGcm3 && cur === p.val));
  });
}

/** 上面填错时，也把密度那句"还缺一个密度"摆出来（和光学的 cvtDemandAux 一个意思） */
function bdPaintRhoHint() {
  const rho = bdReadDensity();
  if (rho.msg) bdHint(bdDensityEl, rho.msg, !rho.hard);
}

/** 进这一层：dir 决定上栏摆体积还是质量。
 *  seed 可选 = { value, unit }：从换算界面那颗跳转过来时，把那边刚敲的数和
 *  单位带过来（用户在体积页填了 12 升，跳过来就是 12 升 → ? 千克）。 */
function bdOpen(dir, seed) {
  bdDir = dir === 'm2v' ? 'm2v' : 'v2m';

  /* 默认摆一对最常用的：升 ⇄ 千克 + 水。
     密度写 0.9982（20 ℃ 的水），不写教科书那个整数 1 —— 快捷键也是这个值，
     一进来「水」那颗就是亮的，两种口径不会打架。 */
  bdSel = bdDir === 'v2m'
    ? { from: 'l', to: 'kg', rho: 'gcm3' }
    : { from: 'kg', to: 'l', rho: 'gcm3' };

  // 带过来的单位只在这边确实有才认（体积的是体积单位、质量的是质量单位）
  if (seed && seed.unit && bdUnit('from', seed.unit)) bdSel.from = seed.unit;

  bdFromEl.value = seed && seed.value ? seed.value : '1';
  bdDensityEl.value = BD_RHO_PRESETS.water.val;
  bdClearHint(bdFromEl);
  bdClearHint(bdDensityEl);

  bdPaintUnits();
  bdSync();

  cvtPadHide();
  cvtClosePicker();
  unitCatsEl.hidden = true;
  unitConvEl.hidden = true;
  unitBridgeEl.hidden = false;
  unitBodyEl.scrollTop = 0;
}

/** 退一层：回到那张换算页（数值和单位都还留着）。 */
function bdBack() {
  unitBridgeEl.hidden = true;
  unitConvEl.hidden = false;
  unitTitleEl.textContent = cvtCatTitle(cvtCat);
  // 先让它显示出来再设 scrollTop：藏着的时候内容高度是 0，设进去会被夹成 0
  unitBodyEl.scrollTop = bdConvScroll;
}

/** 掉头：方向和上下单位一起换，结果挪到上面（密度留着 —— 换的是方向，不是物质）*/
function bdSwap() {
  const moved = bdToEl.value;
  if (moved) bdFromEl.value = moved;

  const from = bdSel.from;
  bdSel.from = bdSel.to;
  bdSel.to = from;
  bdDir = bdDir === 'v2m' ? 'm2v' : 'v2m';

  bdPaintUnits();
  bdSync();
}


/* ==========================================================
   十、搜索
   ----------------------------------------------------------
   两个入口，共用同一套匹配规则（cvtUnitScore）：

     ① 顶部那条（#cvtSearch）—— 跨量搜全库。用户想算「5 匹是多少瓦」，
        他不知道匹在「功率」里，靠的就是这一条。
     ② 选单位弹窗的放大镜（#unitPickerFind）—— 只搜**当前量**，
        就地过滤药丸。跨量的活归 ①，这里不掺和。

   ★ 为什么必须有别名表：搜「匹」要出「公制马力」，字面上一个字都对不上，
     任何子串 / 编辑距离都做不到。别名写在 UNITS 后面的 UNIT_META 里。
   ★ 匹配到的都算（Roy 定的口径）：不做「只给最佳结果」，全列出来，
     每行右边写清归属量 —— 单位 id 跨量重名（ms / h / t / s…），
     不写归属就分不清是时间里的「秒」还是电导里的「西」。
   ========================================================== */

/** 归一化：不分大小写、去掉所有空白。"kg m³" 与 "kgm³" 当同一个输入。 */
function cvtNorm(s) {
  return String(s == null ? '' : s).toLowerCase().replace(/\s+/g, '');
}

/** 转义成 HTML 文本。数据虽然全来自本文件的常量，但拼 innerHTML 前
 *  统一过一道，免得以后有人把用户输入塞进 label。 */
function cvtEsc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/** 逐字顺序出现就算命中：「公马力」→「公制马力」、「milehour」→「mile/hour」。
 *  这是中文里唯一可用的「模糊」—— 没有拼音表，做不到 gongli → 公里。
 *
 *  ★ 两道闸，缺一个都会把结果刷成噪声：
 *    ① 字符太少的查询根本不启用。两个拉丁字母时，几乎每个英文别名都能跳字
 *       命中 —— 搜 "mi" 会捞出 微米（micron）、毫米（millimeter）、天文单位
 *       （astronomical unit）。中文两个字就够（「公马」→「公制马力」）。
 *    ② 命中跨度不超过 q.length * 2 + 2。防止在长串里跨词乱跳，
 *       「公制马力」跨度 4、「mile/hour」跨度 8，都远在阈值内。 */
function cvtSeq(q, s) {
  if (!q) return false;
  const a = Array.from(q);
  const latin = !/[\u3400-\u9FFF]/.test(q);
  if (a.length < (latin ? 3 : 2)) return false;
  const b = Array.from(s);
  let i = 0, first = -1, last = -1;
  for (let k = 0; k < b.length && i < a.length; k++) {
    if (b[k] === a[i]) { if (first < 0) first = k; last = k; i++; }
  }
  if (i < a.length) return false;
  return last - first + 1 <= a.length * 2 + 2;
}

/* 归一化后的别名，按「量/id」缓存 —— 每敲一个字都要过一遍 589 个单位，
   每次重新 map 一遍数组太浪费 */
const cvtAliasCache = new Map();
function cvtAliases(cat, id) {
  const key = cat + '/' + id;
  let v = cvtAliasCache.get(key);
  if (v) return v;
  const m = UNIT_META[cat] && UNIT_META[cat][id];
  v = (m && m.alias ? m.alias : []).map(cvtNorm);
  cvtAliasCache.set(key, v);
  return v;
}

/** 一个单位对查询的得分。0 = 不命中。
 *  分档而不是只判真假，是为了让「米」这种前缀命中排在「平方米」前面。 */
function cvtUnitScore(q, cat, u) {
  const label = cvtNorm(u.label);
  const sym   = cvtNorm(u.sym || '');
  const id    = cvtNorm(u.id);

  if (label === q) return 1000;
  if (label.indexOf(q) === 0) return 940;
  if (label.indexOf(q) > 0) return 880;

  const al = cvtAliases(cat, u.id);
  for (let i = 0; i < al.length; i++) if (al[i] === q) return 900;

  if (sym && sym === q) return 860;
  if (id === q) return 780;

  /* ★ 别名「包含」是宽口径，两个拉丁字母几乎谁都含 —— 搜 "mi" 会把
     微米（micrometer）、毫米（millimeter）、天文单位（astronomical unit）
     全捞出来，而界面上只显示中文名，「mi 到底命中哪了」用户看不出来。
     所以拉丁查询要 ≥3 字符（kil / met / mile 才只剩相关项）；
     中文不受此限 —— 单个汉字信息量大，搜「千」靠别名「千米」命中「公里」
     是正当的（挡掉会白丢结果）。 */
  const latin = !/[\u3400-\u9FFF]/.test(q);
  if (!latin || q.length >= 3) {
    for (let i = 0; i < al.length; i++) {
      const p = al[i].indexOf(q);
      if (p < 0) continue;
      /* ★ 中文单字时，别让「label 里一个汉字都没有」的单位靠别名被捞出来。
         典型是 cc：label 就叫 `cc`，别名 ['立方厘米', 'cubic centimetre']，
         搜「米」命中它 —— 那一行只写 cc，跟「米」半点看不出关系，像乱匹配。
         判据不用「别名位置」，因为那会误伤真正相关的：
         「平方公里」的别名是「平方千米」，搜「千」必须留着它。
         所以只挡 label 全拉丁 / 全符号的单位 —— 这类单位的中文语义
         完全藏在别名里，用户从行上看不出来。 */
      if (!latin && q.length === 1 && p > 0 && !/[\u3400-\u9FFF]/.test(u.label)) continue;
      return 760;
    }
  }
  if (sym && sym.indexOf(q) >= 0) return 700;
  if (id.indexOf(q) >= 0) return 640;

  if (cvtNorm(UNITS[cat].name).indexOf(q) >= 0) return 380;
  const p = UNITS[cat].parent && UNITS[UNITS[cat].parent];
  if (p && cvtNorm(p.name).indexOf(q) >= 0) return 300;

  if (cvtSeq(q, label)) return 460;
  for (let i = 0; i < al.length; i++) if (cvtSeq(q, al[i])) return 400;
  return 0;
}

/** 全库搜一遍，按得分降序；同分保持 UNITS 里的原始顺序（稳定）。 */
function cvtSearchList(q) {
  /* 查询在这里再归一化一次：调用方（cvtRunSearch）已经做过，但这是纯函数，
     留着这道闸以后从控制台或别处直接调（传原文 'Mach'）也不会白返空。 */
  q = cvtNorm(q);
  const out = [];
  let idx = 0;
  Object.keys(UNITS).forEach(cat => {
    const c = UNITS[cat];
    if (!Array.isArray(c.units)) return;
    c.units.forEach(u => {
      const score = cvtUnitScore(q, cat, u);
      if (score > 0) out.push({ cat: cat, u: u, score: score, idx: idx++ });
    });
  });
  out.sort((a, b) => b.score - a.score || a.idx - b.idx);
  return out;
}

/** 「*」的全量清单：按 UNITS 的顺序平铺，不分组。
 *  用户的原话是「每个单位一行，宽度是够的，后面灰色写归属栏就行」。 */
function cvtAllUnits() {
  const out = [];
  Object.keys(UNITS).forEach(cat => {
    const c = UNITS[cat];
    if (!Array.isArray(c.units)) return;
    c.units.forEach(u => out.push({ cat: cat, u: u }));
  });
  return out;
}

/* ---------- 结果列表 ---------- */

function cvtRenderResults(list, headText) {
  cvtResultsHeadEl.textContent = headText;

  cvtResultsListEl.innerHTML = list.map(r => {
    const u = r.u;
    return '<button type="button" class="cvt-sr" data-cat="' + r.cat + '" data-id="' + cvtEsc(u.id) + '">'
      +   '<span class="cvt-sr-name">' + cvtEsc(u.label) + '</span>'
      +   (u.sym ? '<span class="cvt-sr-sym">' + cvtEsc(u.sym) + '</span>' : '')
      /* 右顶格的归属量：子量写成「电学-电压」，和顶栏标题同一个口径 */
      +   '<span class="cvt-sr-cat">' + cvtEsc(cvtCatTitle(r.cat)) + '</span>'
      + '</button>';
  }).join('');

  cvtResultsEl.hidden = false;
  unitCatsEl.hidden = true;
  unitSubsEl.hidden = true;
  unitSettingsEl.hidden = true;
  unitSelfEl.hidden = true;
}

/** 点一行：就地展开两颗按钮。一次只开一行（开了新的就把旧的收掉），
 *  不然滚下去满屏都是按钮，反而看不清哪个是哪行的。 */
function cvtResultRowToggle(row) {
  const next = row.nextElementSibling;
  const wasOpen = !!(next && next.classList.contains('cvt-sr-acts'));

  $$('.cvt-sr-acts', cvtResultsListEl).forEach(n => n.remove());
  $$('.cvt-sr.is-open', cvtResultsListEl).forEach(n => n.classList.remove('is-open'));
  if (wasOpen) return;

  row.classList.add('is-open');
  const acts = document.createElement('div');
  acts.className = 'cvt-sr-acts';
  acts.dataset.cat = row.dataset.cat;
  acts.dataset.id = row.dataset.id;
  acts.innerHTML = '<button type="button" class="cvt-sr-act" data-sr-act="from">设为原始单位</button>'
                 + '<button type="button" class="cvt-sr-act" data-sr-act="to">设为目标单位</button>';
  row.after(acts);
}

/** 从搜索结果进换算页。
 *  「设为原始」之后弹那条 5 秒的引导 —— 用户十有八九还要选目标单位，
 *  但**不能**替他选（每个量第二个单位是什么，只有他知道）。 */
function cvtResultPick(cat, id, which) {
  cvtCloseSearch(false);          // false = 别把列表再铺回来，马上要进换算页
  if (which === 'from') {
    cvtOpenCat(cat, id, null);
    cvtGuideShow();
  } else {
    cvtOpenCat(cat, null, id);
  }
}

/* ---------- 搜索视图的开关 ---------- */

let cvtSearchTimer = 0;
let cvtSearchBack = 'cats';       // 搜索是从哪一层发起的：'cats' | 'kids'

function cvtResetSearchBox() {
  clearTimeout(cvtSearchTimer);
  cvtSearchInput.value = '';
  cvtSearchClear.hidden = true;
  cvtResultsEl.hidden = true;
}

function cvtCloseSearch(restore) {
  const wasOpen = !cvtResultsEl.hidden;
  cvtResetSearchBox();
  if (!wasOpen || restore === false) return;
  if (cvtSearchBack === 'kids' && cvtParent) cvtShowKids(cvtParent, true);
  else cvtShowCats();
}

function cvtRunSearch(raw) {
  const q = String(raw || '').trim();
  if (!q) { cvtCloseSearch(); return; }

  if (cvtResultsEl.hidden) cvtSearchBack = unitSubsEl.hidden ? 'cats' : 'kids';

  /* 「*」= 全部单位。这个入口是留给自己排查用的（Roy 说的），
     所以要**真的全**：589 条平铺，一个不落、也不按量分组。 */
  if (q === '*') {
    const all = cvtAllUnits();
    cvtRenderResults(all, '全部单位 · ' + all.length + ' 条');
    return;
  }

  const list = cvtSearchList(cvtNorm(q));
  cvtRenderResults(list, list.length ? '找到 ' + list.length + ' 个匹配单位' : '没找到匹配的单位');
}

function cvtSearchInputChanged() {
  const q = cvtSearchInput.value.trim();
  cvtSearchClear.hidden = !q;
  clearTimeout(cvtSearchTimer);
  cvtSearchTimer = setTimeout(() => cvtRunSearch(q), 140);
}

/* ==========================================================
   十一、显示设置（全部 / 常用 / 自定义）
   ----------------------------------------------------------
   只影响「选单位弹窗里列哪些药丸」，不影响搜索结果，也不影响
   体积⇄质量那张桥卡（那三张单位表不走 UNIT_META）。

   存在 localStorage，**不跟账号走**（项目里其它偏好也这样）。
   要跨设备同步再说 —— 导出 / 导入 json 就是给这件事留的后门。
   ========================================================== */

const CVT_VIEW_KEY = 'nova_units_view';

/* mode: 'all' | 'common' | 'custom'
   hidden: ['cat/id', …]，只在 custom 下生效（黑名单 = 新加的单位默认可见）
   touched: 用户有没有手动动过开关（用来判断「从常用切到自定义」时
            要不要把非常用的先填成关闭）
   sort: 'asc' | 'desc' | 'sem' —— 弹窗列表的顺序，默认升序 */
let cvtView = cvtViewLoad();
let cvtHiddenSet = new Set();
cvtHiddenSet = new Set(cvtView.hidden);

function cvtViewLoad() {
  let o = null;
  try { o = JSON.parse(localStorage.getItem(CVT_VIEW_KEY) || 'null'); } catch (e) { o = null; }
  const mode = o && (o.mode === 'common' || o.mode === 'custom') ? o.mode : 'all';
  const sort = o && (o.sort === 'desc' || o.sort === 'sem') ? o.sort : 'asc';
  return {
    mode: mode,
    sort: sort,
    hidden: o && Array.isArray(o.hidden) ? o.hidden.filter(x => typeof x === 'string') : [],
    touched: !!(o && o.touched),
  };
}

function cvtViewSave() {
  cvtHiddenSet = new Set(cvtView.hidden);
  try {
    localStorage.setItem(CVT_VIEW_KEY, JSON.stringify({
      mode: cvtView.mode, sort: cvtView.sort,
      hidden: cvtView.hidden, touched: cvtView.touched,
    }));
  } catch (e) { /* 隐私模式写不进去：本次会话照样有效，不吵用户 */ }
}

const cvtKey = (cat, id) => cat + '/' + id;

function cvtMetaOf(cat, id) {
  const m = UNIT_META[cat];
  return (m && m[id]) || null;
}

function cvtIsCommon(cat, id) {
  const m = cvtMetaOf(cat, id);
  return !!(m && m.common);
}

/** 这个单位现在该不该出现在「选单位」里 */
function cvtVisible(cat, u) {
  if (cvtView.mode === 'all') return true;
  if (cvtView.mode === 'common') return cvtIsCommon(cat, u.id);
  return !cvtHiddenSet.has(cvtKey(cat, u.id));
}

/* ---------- 排序：一句话口径 ----------
   大小 = 「1 个该单位等于多少基准」。
     有 k 的直接用 k（1 km = 1000 m）；
     没 k 的（温度词头、比重刻度、点距）**现算 toBase(1) − toBase(0)** ——
     这个差正好是「刻度走一格折合多少基准」，仿射刻度（℃↔℉）和非线性刻度
     （API 度、点距）都能算出一个可比的数。
     差为 0 的是「点」不是「刻度」（绝对零度、三相点），没大小可言 → 沉到组尾。

   ★ 只在**组内**排，组的先后一律不动。组边界是语义的（光学那四组是四个
     不同的物理量，混排会把流明和尼特搅在一块），跨组按大小穿插只会更难读。
   ★ 等值的保持原序（cc 与立方厘米、dpi 与 ppi 谁先谁后无所谓，别让刷新一次
     顺序就跳一次）。 */
function cvtUnitSize(catKey, u) {
  if (typeof u.k === 'number' && u.k > 0) return u.k;
  /* 温度词头：条目本身没 k，系数在 CVT_K_PREFIX 里。
     ★ 这一支**不能**留给下面的 toBase 反算 —— 273.15 那个偏移量会把小刻度
     整个吞掉（double 在 273 附近的 ulp 约 5.7e-14，所以 1e-30、1e-24…
     1e-15 那八档算出来都是 0，整段沉到组尾）。 */
  if (CVT_K_PREFIX[u.id] > 0) return CVT_K_PREFIX[u.id];
  const cat = UNITS[catKey];
  if (cat && typeof cat.toBase === 'function') {
    const v1 = cat.toBase(1, u.id);
    const v0 = cat.toBase(0, u.id);
    if (isFinite(v1) && isFinite(v0)) {
      const d = Math.abs(v1 - v0);
      if (d > 0) return d;
    }
  }
  return null;
}

/** 按当前设置排一遍（'sem' 原样返回 —— 表内顺序本来就是语义顺序）。 */
function cvtSortUnits(catKey, list) {
  if (cvtView.sort !== 'asc' && cvtView.sort !== 'desc') return list;
  const dir = cvtView.sort === 'desc' ? -1 : 1;

  /* 先按 group 切成连续的段（同一个组名出现两次算两段，本来就该各排各的） */
  const segs = [];
  let seg = null;
  list.forEach(u => {
    const g = u.group || '';
    if (!seg || seg.g !== g) { seg = { g: g, arr: [] }; segs.push(seg); }
    seg.arr.push(u);
  });

  const out = [];
  segs.forEach(s => {
    s.arr
      .map((u, i) => ({ u: u, i: i, s: cvtUnitSize(catKey, u) }))
      .sort(function (a, b) {
        const an = a.s === null;
        const bn = b.s === null;
        if (an !== bn) return an ? 1 : -1;      // 比不出大小的沉到组尾
        if (an) return a.i - b.i;
        if (a.s === b.s) return a.i - b.i;      // 等值保持原序
        return dir * (a.s - b.s);
      })
      .forEach(x => out.push(x.u));
  });
  return out;
}

/** 某一栏该回退到哪个单位（当前那个被显示设置藏了时用）。
 *  preferId：这一档的默认单位（它可见就直接用它）
 *  excludeId：另一栏已经占了，不能再挑同一个
 *  顺序：默认 → 可见集里第一个常用 → 可见集第一个 → 兜底用被藏的 */
function cvtFallbackUnit(catKey, preferId, excludeId) {
  const cat = UNITS[catKey];
  if (!cat || !Array.isArray(cat.units)) return preferId;

  if (preferId !== excludeId) {
    const p = cat.units.find(u => u.id === preferId);
    if (p && cvtVisible(catKey, p)) return preferId;
  }

  const vis = cat.units.filter(u => cvtVisible(catKey, u) && u.id !== excludeId);
  const com = vis.filter(u => cvtIsCommon(catKey, u.id));

  /* 常用的里面优先挑**离默认单位最近**的那个，且**先往小的一侧找**：
     把厘米关掉以后，默认 to 该落到毫米（同侧最近），而不是英寸 ——
     英寸按比值算虽然更近（2.54 倍），但跨了制式，看着莫名其妙。
     同侧都没有才去另一侧。（温度那档没有 k，直接取常用集第一个。） */
  if (com.length) {
    const pref = cat.units.find(u => u.id === preferId);
    if (pref && pref.k > 0) {
      const nearest = (arr) => {
        let best = null;
        let bestD = Infinity;
        arr.forEach(u => {
          if (!(u.k > 0)) return;
          const d = Math.abs(Math.log(u.k / pref.k));
          if (d < bestD - 1e-12) { bestD = d; best = u; }
        });
        return best;
      };
      const smaller = com.filter(u => u.k > 0 && u.k <= pref.k);
      const bigger  = com.filter(u => u.k > 0 && u.k > pref.k);
      const pick = nearest(smaller) || nearest(bigger);
      if (pick) return pick.id;
    }
    return com[0].id;
  }
  if (vis.length) return vis[0].id;

  /* 可见单位只剩 0~1 个（用户手动关到只剩一个）：只能拿被藏的凑一对，
     不然这个量就彻底换算不了了 */
  if (preferId !== excludeId) return preferId;
  const any = cat.units.find(u => u.id !== excludeId);
  return any ? any.id : preferId;
}

/** 一个量的单位总数 / 可见数（父领域把 kids 加起来） */
function cvtCatTotalCount(k) {
  const c = UNITS[k];
  if (!c) return 0;
  return c.kids ? c.kids.reduce((s, x) => s + cvtCatTotalCount(x), 0) : c.units.length;
}
function cvtCatVisibleCount(k) {
  const c = UNITS[k];
  if (!c) return 0;
  return c.kids ? c.kids.reduce((s, x) => s + cvtCatVisibleCount(x), 0)
                : c.units.reduce((s, u) => s + (cvtVisible(k, u) ? 1 : 0), 0);
}

function cvtShowSettings() {
  cvtClosePicker();
  cvtPadHide();
  cvtGuideHide();
  cvtHideViews();
  cvtParent = '';
  unitSettingsEl.hidden = false;
  unitTitleEl.textContent = '显示设置';
  cvtPaintSettings();
  cvtSyncTopbar();
  unitBodyEl.scrollTop = 0;
}

function cvtPaintSettings() {
  $$('[data-cvt-mode]', unitSettingsEl).forEach(btn => {
    btn.setAttribute('aria-checked', String(btn.dataset.cvtMode === cvtView.mode));
  });
  $$('[data-cvt-sort]', unitSettingsEl).forEach(btn => {
    btn.setAttribute('aria-checked', String(btn.dataset.cvtSort === cvtView.sort));
  });

  const all = Object.keys(UNITS).filter(k => !UNITS[k].parent)
    .reduce((s, k) => s + cvtCatTotalCount(k), 0);
  const common = (function () {
    let n = 0;
    Object.keys(UNITS).forEach(cat => {
      if (!Array.isArray(UNITS[cat].units)) return;
      UNITS[cat].units.forEach(u => { if (cvtIsCommon(cat, u.id)) n++; });
    });
    return n;
  })();

  const a = $('[data-cvt-count="all"]', unitSettingsEl);
  if (a) a.textContent = all + ' 个单位全部列出';

  const cm = $('[data-cvt-count="common"]', unitSettingsEl);
  if (cm) cm.textContent = '每个量留最常用的几档，共 ' + common + ' 个';

  const cu = $('[data-cvt-count="custom"]', unitSettingsEl);
  if (cu) {
    cu.textContent = cvtView.mode === 'custom'
      ? '当前 ' + (function () {
          return Object.keys(UNITS).filter(k => !UNITS[k].parent)
            .reduce((s, k) => s + cvtCatVisibleCount(k), 0);
        })() + ' / ' + all + ' 个可见'
      : '逐个开关，可导出 / 导入 json';
  }
}

function cvtSetMode(mode) {
  if (mode === 'custom') { cvtEnterCustom(); return; }
  cvtView.mode = mode;
  cvtViewSave();
  cvtPaintSettings();
  cvtEnsureSelVisible();
}

/** 换排序方式。设置页里弹窗是关着的，所以不用立刻重画 —— 下次打开就按新顺序。
 *  （若哪天设置能跟弹窗同时开着，这里补一句 cvtRenderChips() 即可。） */
function cvtSetSort(mode) {
  if (mode !== 'asc' && mode !== 'desc' && mode !== 'sem') return;
  cvtView.sort = mode;
  cvtViewSave();
  cvtPaintSettings();
}

/* ==========================================================
   十二、自定义显示（整页子视图，三层：领域 → 量 → 单位）
   ========================================================== */

let cvtSelfLevel = 0;        // 0 领域 / 1 量 / 2 单位
let cvtSelfParent = '';      // 领域键（单位列表退回时用）
let cvtSelfCat = '';         // 当前打开的量
let cvtSelfTimer = 0;

/** 进自定义页。从「只显示常用」切过来时，如果用户从没手动开过关，
 *  先把非常用的填进黑名单 —— 灯不跳变，不然一进去看着像「全开了」。 */
function cvtEnterCustom() {
  const wasCommon = cvtView.mode === 'common';
  cvtView.mode = 'custom';
  if (wasCommon && !cvtView.touched) {
    cvtView.hidden = [];
    Object.keys(UNITS).forEach(cat => {
      if (!Array.isArray(UNITS[cat].units)) return;
      UNITS[cat].units.forEach(u => {
        if (!cvtIsCommon(cat, u.id)) cvtView.hidden.push(cvtKey(cat, u.id));
      });
    });
  }
  cvtViewSave();
  cvtShowSelf();
}

function cvtShowSelf() {
  cvtClosePicker();
  cvtPadHide();
  cvtGuideHide();
  cvtHideViews();
  unitSelfEl.hidden = false;
  unitTitleEl.textContent = '自定义显示';
  cvtSelfLevel = 0;
  cvtSelfParent = '';
  cvtSelfCat = '';
  cvtSelfSearch.value = '';
  cvtSelfSearchClear.hidden = true;
  cvtSelfRenderCats();
  cvtSyncTopbar();
  unitBodyEl.scrollTop = 0;
}

/** 自定义页里那种卡片（复用首页的 .tool-btn.unit-cat）：
 *  图标块放这个量有多少个单位，右下角写「可见 / 总数」。 */
function cvtSelfCardHtml(key, attr, title, sub, glyph) {
  const g = String(glyph);
  const cls = g.length >= 4 ? ' is-long' : g.length === 3 ? ' is-mid' : '';
  return '<button type="button" class="tool-btn unit-cat" ' + attr + '="' + cvtEsc(key) + '">'
    +   '<span class="tool-btn-ico unit-kid-sym' + cls + '" aria-hidden="true">' + cvtEsc(g) + '</span>'
    +   '<span class="tool-btn-text"><span class="tool-btn-name">' + cvtEsc(title) + '</span>'
    +     '<span class="tool-btn-desc">' + cvtEsc(sub) + '</span></span>'
    +   '<span class="tool-btn-go" aria-hidden="true">'
    +     '<svg viewBox="0 0 24 24" fill="none" stroke-width="2.2" stroke-linecap="round"'
    +          ' stroke-linejoin="round"><path d="M9 5l7 7-7 7" /></svg>'
    +   '</span>'
    + '</button>';
}

function cvtSelfRenderCats() {
  const keys = Object.keys(UNITS).filter(k => !UNITS[k].parent);
  unitSelfCatsEl.innerHTML = keys.map(k => cvtSelfCardHtml(
    k, 'data-self-group', UNITS[k].name,
    cvtCatVisibleCount(k) + ' / ' + cvtCatTotalCount(k) + ' 可见',
    cvtCatTotalCount(k)
  )).join('');
  unitSelfCatsEl.hidden = false;
  unitSelfUnitsEl.hidden = true;
}

function cvtSelfRenderKids(parentKey) {
  const p = UNITS[parentKey];
  unitSelfCatsEl.innerHTML = p.kids.map(k => {
    const c = UNITS[k];
    return cvtSelfCardHtml(
      k, 'data-self-group', c.name,
      cvtCatVisibleCount(k) + ' / ' + cvtCatTotalCount(k) + ' 可见',
      c.glyph || c.units.length
    );
  }).join('');
  unitSelfCatsEl.hidden = false;
  unitSelfUnitsEl.hidden = true;
}

function cvtSelfOpenGroup(key) {
  const c = UNITS[key];
  if (!c) return;
  if (c.kids) {
    cvtSelfLevel = 1;
    cvtSelfParent = key;
    cvtSelfCat = '';
    cvtSelfRenderKids(key);
  } else {
    cvtSelfLevel = 2;
    cvtSelfParent = c.parent || '';
    cvtSelfCat = key;
    cvtSelfRenderUnits(key);
  }
  unitBodyEl.scrollTop = 0;
}

/** 一行单位（勾选行）。showCat = 搜索结果模式，名字后面补上归属量。 */
function cvtSelfUnitRow(cat, u, showCat) {
  const on = cvtVisible(cat, u);
  return '<button type="button" class="cvt-self-row" data-self-cat="' + cvtEsc(cat) + '"'
    +   ' data-self-id="' + cvtEsc(u.id) + '" role="checkbox" aria-checked="' + on + '">'
    +   '<span class="cvt-self-name">' + cvtEsc(u.label)
    +     (u.sym ? '<em>' + cvtEsc(u.sym) + '</em>' : '')
    +     (showCat ? '<em class="cvt-self-cat">' + cvtEsc(cvtCatTitle(cat)) + '</em>' : '')
    +   '</span>'
    +   '<span class="cvt-self-switch" aria-hidden="true"></span>'
    + '</button>';
}

function cvtSelfRenderUnits(catKey) {
  const c = UNITS[catKey];
  const rows = c.units.map(u => cvtSelfUnitRow(catKey, u, false)).join('');
  unitSelfUnitsEl.innerHTML =
      '<div class="cvt-self-head"><span>' + cvtEsc(cvtCatTitle(catKey)) + ' · ' + c.units.length + ' 个单位</span>'
    + '<button type="button" class="cvt-self-all" data-self-all="' + cvtEsc(catKey) + '">全选 / 全不选</button></div>'
    + rows;
  unitSelfUnitsEl.hidden = false;
  unitSelfCatsEl.hidden = true;
}

/** 勾上 / 取消一个单位。动过一次就进 custom 模式（开关本身就是自定义的产物）。 */
function cvtSelfSet(cat, id, on, silent) {
  const k = cvtKey(cat, id);
  const i = cvtView.hidden.indexOf(k);
  if (on && i >= 0) cvtView.hidden.splice(i, 1);
  if (!on && i < 0) cvtView.hidden.push(k);
  cvtView.mode = 'custom';
  cvtView.touched = true;
  if (!silent) cvtViewSave();
  else cvtHiddenSet = new Set(cvtView.hidden);
}

function cvtSelfClickRow(row) {
  const cat = row.dataset.selfCat;
  const id = row.dataset.selfId;
  const on = row.getAttribute('aria-checked') !== 'true';
  cvtSelfSet(cat, id, on);
  row.setAttribute('aria-checked', String(on));
}

function cvtSelfToggleAll(catKey) {
  const c = UNITS[catKey];
  if (!c) return;
  const allOn = c.units.every(u => cvtVisible(catKey, u));
  c.units.forEach(u => cvtSelfSet(catKey, u.id, !allOn, true));
  cvtViewSave();
  cvtSelfRenderUnits(catKey);
}

/* ---------- 自定义页里的搜索 ---------- */

function cvtSelfRenderSearch(q) {
  const list = q === '*' ? cvtAllUnits() : cvtSearchList(cvtNorm(q));
  unitSelfUnitsEl.innerHTML =
      '<div class="cvt-self-head"><span>' + (q === '*' ? '全部单位 · ' + list.length + ' 个' : '找到 ' + list.length + ' 个')
    + ' · 点一行开关</span></div>'
    + list.map(r => cvtSelfUnitRow(r.cat, r.u, true)).join('');
  unitSelfUnitsEl.hidden = false;
  unitSelfCatsEl.hidden = true;
}

function cvtSelfClearSearch() {
  cvtSelfSearch.value = '';
  cvtSelfSearchClear.hidden = true;
  if (cvtSelfLevel === 2 && cvtSelfCat) cvtSelfRenderUnits(cvtSelfCat);
  else if (cvtSelfLevel === 1 && cvtSelfParent) cvtSelfRenderKids(cvtSelfParent);
  else cvtSelfRenderCats();
}

/** 自定义页退一层。返回 false = 已在最上层（领域列表），该退回设置页了。 */
function cvtSelfBack() {
  if (cvtSelfSearch.value.trim()) { cvtSelfClearSearch(); return true; }
  if (!unitSelfUnitsEl.hidden) {
    if (cvtSelfParent) { cvtSelfLevel = 1; cvtSelfRenderKids(cvtSelfParent); }
    else { cvtSelfLevel = 0; cvtSelfCat = ''; cvtSelfRenderCats(); }
    return true;
  }
  if (cvtSelfLevel === 1) { cvtSelfLevel = 0; cvtSelfParent = ''; cvtSelfRenderCats(); return true; }
  return false;
}

/* ---------- 导出 / 导入 json ----------
   格式是给自己看的，机器读得懂就行（Roy：玩家不看这个）：
     { app: 'nova-units', v: 1, mode: 'custom', hidden: ['length/cm', …] }
   hidden 是**黑名单**：新增的单位默认可见，不会因为换了份旧配置就消失。
   键必须带量前缀（length/cm），裸 id 会撞 —— 29 个单位 id 跨量重名。 */

function cvtExportJson() {
  const data = {
    app: 'nova-units',
    v: 1,
    mode: cvtView.mode,
    hidden: cvtView.hidden.slice(),
  };
  let ok = false;
  try {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'nova-units-display.json';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1500);
    ok = true;
  } catch (e) { ok = false; }

  if (ok) toast('ok', '已导出', 'nova-units-display.json');
  else toast('err', '导出失败', '这个浏览器不让下载文件');
}

function cvtImportJson(text) {
  let data = null;
  try { data = JSON.parse(text); } catch (e) { data = null; }
  if (!data || typeof data !== 'object' || !Array.isArray(data.hidden)) {
    toast('err', '导入失败', '这不是本工具的 json');
    return;
  }

  /* 只认「量/单位」且真的存在的那几条；id 改过名 / 量下线的计入 ignored。
     key 用 Set 校验，589 × n 也不慢。 */
  const valid = new Set();
  Object.keys(UNITS).forEach(cat => {
    if (!Array.isArray(UNITS[cat].units)) return;
    UNITS[cat].units.forEach(u => valid.add(cat + '/' + u.id));
  });

  let ignored = 0;
  const hidden = [];
  const seen = new Set();
  data.hidden.forEach(k => {
    if (typeof k !== 'string') { ignored++; return; }
    if (!valid.has(k)) { ignored++; return; }
    if (seen.has(k)) return;          // 同一个键写两遍：静默跳过，不算忽略
    seen.add(k);
    hidden.push(k);
  });

  cvtView.mode = 'custom';
  cvtView.hidden = hidden;
  cvtView.touched = true;
  cvtViewSave();

  if (!unitSelfEl.hidden) cvtSelfClearSearch();
  cvtPaintSettings();

  toast('ok', '已导入',
    hidden.length + ' 个单位已关闭' + (ignored ? '，忽略 ' + ignored + ' 条不存在的' : ''));
}

function cvtEnsureSelVisible() {
  const cat = UNITS[cvtCat];
  if (!cat || !Array.isArray(cat.units)) return;
  if (unitConvEl.hidden) return;          // 不在换算页就不用管

  const vis = cat.units.filter(u => cvtVisible(cvtCat, u));
  if (!vis.length) return;

  let changed = false;
  if (!vis.some(u => u.id === cvtSel.from)) { cvtSel.from = vis[0].id; changed = true; }
  if (!vis.some(u => u.id === cvtSel.to)) {
    cvtSel.to = (vis.find(u => u.id !== cvtSel.from) || vis[0]).id;
    changed = true;
  }
  if (!changed) return;

  cvtPaintUnits();
  cvtSync();
  toast('i', '单位已换', '刚才那一档被隐藏了');
}

/* ==========================================================
   十三、视图切换的公共部分 + 5 秒引导条
   ========================================================== */

/** 把所有「整块视图」收起来。各层自己 show 时只打开自己那一块。 */
function cvtHideViews() {
  unitCatsEl.hidden = true;
  unitSubsEl.hidden = true;
  unitConvEl.hidden = true;
  unitBridgeEl.hidden = true;
  unitSettingsEl.hidden = true;
  unitSelfEl.hidden = true;
  cvtResultsEl.hidden = true;
}

/** 顶部搜索条露不露：换算页 / 桥卡 / 设置 / 自定义都不要它
 *  （换算页要换单位点单位按钮，后两页各有自己的搜索框）。
 *  例外是**结果页**：它就是这条框长出来的，收了没法改词 —— 所以结果一露，
 *  顶栏跟着露（正常路径下结果页是从类别页/子页开的，底下本来就没有换算页）。 */
function cvtSyncTopbar() {
  if (!cvtResultsEl.hidden) { cvtTopbarEl.hidden = false; return; }
  cvtTopbarEl.hidden = !unitConvEl.hidden || !unitBridgeEl.hidden
                    || !unitSettingsEl.hidden || !unitSelfEl.hidden;
}

/* ---------- 5 秒引导条（从搜索「设为原始」进来时才有） ----------
   为什么是**浮条**不是 modal：用户马上要开始敲数，modal 会挡路；
   5 秒后自动收；点取消 / 开始操作输入框也收。 */
let cvtGuideEl = null;
let cvtGuideTimer = 0;

function cvtGuideShow() {
  if (!cvtGuideEl) {
    cvtGuideEl = document.createElement('div');
    cvtGuideEl.className = 'cvt-guide';
    cvtGuideEl.hidden = true;
    cvtGuideEl.innerHTML =
        '<span class="cvt-guide-txt">已设为原始单位</span>'
      + '<button type="button" class="cvt-guide-btn" data-guide="find">搜索目标单位</button>'
      + '<button type="button" class="cvt-guide-x" data-guide="cancel">取消</button>';
    UNIT_PAGE.appendChild(cvtGuideEl);
  }
  cvtGuideEl.hidden = false;
  cvtGuideEl.classList.remove('is-in');
  void cvtGuideEl.offsetWidth;        // 强制回流，动画才会重播
  cvtGuideEl.classList.add('is-in');

  clearTimeout(cvtGuideTimer);
  cvtGuideTimer = setTimeout(cvtGuideHide, 5000);
}

function cvtGuideHide() {
  clearTimeout(cvtGuideTimer);
  if (cvtGuideEl) cvtGuideEl.hidden = true;
}

/* ==========================================================
   十四、事件接线
   ========================================================== */

/* ---- 顶部搜索 ---- */
cvtSearchInput.addEventListener('input', cvtSearchInputChanged);
cvtSearchInput.addEventListener('keydown', e => {
  if (e.key !== 'Enter') return;
  e.preventDefault();
  clearTimeout(cvtSearchTimer);
  cvtRunSearch(cvtSearchInput.value);
});
cvtSearchClear.addEventListener('click', () => {
  cvtResetSearchBox();
  if (cvtSearchBack === 'kids' && cvtParent) cvtShowKids(cvtParent, true);
  else cvtShowCats();
});

cvtResultsListEl.addEventListener('click', e => {
  const act = e.target.closest('[data-sr-act]');
  if (act) {
    const box = act.parentElement;
    cvtResultPick(box.dataset.cat, box.dataset.id, act.dataset.srAct);
    return;
  }
  const row = e.target.closest('.cvt-sr');
  if (row) cvtResultRowToggle(row);
});

/* ---- 齿轮 → 显示设置 ---- */
cvtSettingsBtn.addEventListener('click', cvtShowSettings);
unitSettingsEl.addEventListener('click', e => {
  const sort = e.target.closest('[data-cvt-sort]');
  if (sort) { cvtSetSort(sort.dataset.cvtSort); return; }
  const opt = e.target.closest('[data-cvt-mode]');
  if (opt) cvtSetMode(opt.dataset.cvtMode);
});

/* ---- 自定义页 ---- */
unitSelfCatsEl.addEventListener('click', e => {
  const card = e.target.closest('[data-self-group]');
  if (card) cvtSelfOpenGroup(card.dataset.selfGroup);
});
unitSelfUnitsEl.addEventListener('click', e => {
  const all = e.target.closest('[data-self-all]');
  if (all) { cvtSelfToggleAll(all.dataset.selfAll); return; }
  const row = e.target.closest('[data-self-cat]');
  if (row) cvtSelfClickRow(row);
});

cvtSelfSearch.addEventListener('input', () => {
  const q = cvtSelfSearch.value.trim();
  cvtSelfSearchClear.hidden = !q;
  clearTimeout(cvtSelfTimer);
  cvtSelfTimer = setTimeout(() => {
    if (q) cvtSelfRenderSearch(q);
    else cvtSelfClearSearch();
  }, 140);
});
cvtSelfSearchClear.addEventListener('click', () => {
  clearTimeout(cvtSelfTimer);
  cvtSelfClearSearch();
});

cvtExportBtn.addEventListener('click', cvtExportJson);
cvtImportBtn.addEventListener('click', () => cvtImportFile.click());
cvtImportFile.addEventListener('change', () => {
  const f = cvtImportFile.files && cvtImportFile.files[0];
  cvtImportFile.value = '';               // 清掉，同一个文件也能再导一次
  if (!f) return;
  const reader = new FileReader();
  reader.onload = () => cvtImportJson(String(reader.result || ''));
  reader.onerror = () => toast('err', '导入失败', '这个文件读不了');
  reader.readAsText(f);
});

/* ---- 选单位弹窗的放大镜 ---- */
function cvtFindbarOpen(on) {
  unitPickerFindBar.hidden = !on;
  unitPickerFindBtn.setAttribute('aria-expanded', String(!!on));
  if (!on) {
    unitPickerFindInput.value = '';
    unitPickerFindClear.hidden = true;
  }
}

unitPickerFindBtn.addEventListener('click', () => {
  const on = unitPickerFindBar.hidden;
  cvtFindbarOpen(on);
  cvtRenderChips();
  if (on) setTimeout(() => unitPickerFindInput.focus(), 30);
});
unitPickerFindInput.addEventListener('input', () => {
  unitPickerFindClear.hidden = !unitPickerFindInput.value.trim();
  cvtRenderChips();
});
unitPickerFindInput.addEventListener('keydown', e => {
  if (e.key !== 'Enter') return;
  e.preventDefault();
  // 只有一个结果时，回车直接选中 —— 手机上省一次点击
  const chips = $$('.chip', unitPickerChips);
  if (chips.length === 1) chips[0].click();
});
unitPickerFindClear.addEventListener('click', () => {
  unitPickerFindInput.value = '';
  unitPickerFindClear.hidden = true;
  cvtRenderChips();
  unitPickerFindInput.focus();
});

/* ---- 5 秒引导条 ---- */
UNIT_PAGE.addEventListener('click', e => {
  const g = e.target.closest('[data-guide]');
  if (!g) return;
  if (g.dataset.guide === 'find') {
    cvtGuideHide();
    cvtOpenPicker('to');
    cvtFindbarOpen(true);
    cvtRenderChips();
    setTimeout(() => unitPickerFindInput.focus(), 60);
  } else {
    cvtGuideHide();
  }
});

/* 开始敲数就说明他知道目标单位是谁了，别让那条浮着挡路 */
cvtFrom.addEventListener('input', cvtGuideHide);
cvtFrom.addEventListener('focus', cvtGuideHide);

/* ==========================================================
   十五、事件绑定
   ========================================================== */

/* ---- 选类别 / 选量 ----
   两层列表共用同一套卡片外观，但容器不同：第一层是写死在 index.html 里的
   #unitCats（每张卡有自己的 SVG 图标），第二层是 cvtRenderKids 现画的
   #unitSubs。两边都靠 data-* 认卡片，点下去都进同一个 cvtOpenCat。
   父领域（electric 之类）在 cvtOpenCat 里会被转到 cvtShowKids。 */
unitCatsEl.addEventListener('click', e => {
  const card = e.target.closest('[data-unit-cat]');
  if (!card) return;
  cvtOpenCat(card.dataset.unitCat);
});

unitSubsEl.addEventListener('click', e => {
  const card = e.target.closest('[data-unit-kid]');
  if (!card) return;
  cvtOpenCat(card.dataset.unitKid);
});

/* ---- 数值输入：先过滤字符，再判读整串 ---- */
cvtFrom.addEventListener('input', () => {
  cvtFilter(cvtFrom);
  cvtSync();
});

/* ---- 副输入：立体角 / 面积 ----
   过滤换一套放行表（多一个 π），其余和主框一个套路：先过字符，再重算。
   注意 .chip 上的 aria-checked 也要跟着刷 —— 用户手敲一个 1 进 Ω 栏时，
   那三个药丸该亮不亮得跟着变。 */
cvtAuxOmegaEl.addEventListener('input', () => {
  cvtFilter(cvtAuxOmegaEl, cvtAuxChar);
  cvtPaintAuxChips();
  cvtSync();
});
cvtAuxAreaEl.addEventListener('input', () => {
  cvtFilter(cvtAuxAreaEl);
  cvtSync();
});

/* ---- 常用立体角药丸：4π / 2π / π 一键填进去 ----
   软键盘上虽然也有个 π 键了，但这三个值是最常敲的，点一下就是一整串
   （省掉「4」再点「π」两下），所以药丸留着。
   填完那个框里就是普通文本，用户还能接着往后补（4π → 4π/3 之类）。 */
cvtAuxOmegaChips.addEventListener('click', e => {
  const chip = e.target.closest('[data-cvt-omega]');
  if (!chip) return;

  cvtAuxOmegaEl.value = chip.dataset.cvtOmega;
  clearError(cvtAuxOmegaEl);
  cvtPaintAuxChips();
  cvtSync();

  // 点药丸就是"点一下就完事"：手机、电脑都**不要**弹软键盘（focus 会触发键盘）。
  // 真要接着敲（比如 4π → 4π/3），去点输入框，键盘自然就出来。
  cvtPadHide();
});

/* ---- 交换 ---- */
cvtSwapBtn.addEventListener('click', cvtSwap);

/* ---- 体积 ⇄ 质量：两个数各改各的，改完就重算 ----
   密度那一栏也走同一套字符白名单（°API 这种读数是数字，不是字母） */
bdFromEl.addEventListener('input', () => {
  cvtFilter(bdFromEl);
  bdSync();
});
bdDensityEl.addEventListener('input', () => {
  cvtFilter(bdDensityEl);
  bdSync();
});
bdSwapBtn.addEventListener('click', bdSwap);

/* ---- 密度快捷键：填数 + 把密度单位切回 g/cm³（这几组数就是按它写的） ----
   和光学的立体角药丸一样：点一下就是一整串，**不**顺手 focus（手机上会弹键盘）。
   填完仍是普通文本，用户还能接着改（7.874 → 7.9 之类）。 */
if (bdRhoChipsEl) {
  bdRhoChipsEl.addEventListener('click', e => {
    const chip = e.target.closest('[data-bd-rho]');
    if (!chip) return;

    const p = BD_RHO_PRESETS[chip.dataset.bdRho];
    if (!p) return;

    bdDensityEl.value = p.val;
    bdSel.rho = 'gcm3';
    bdClearHint(bdDensityEl);
    bdPaintUnits();          // 按钮上的单位名跟着换（可能刚从 °API 回来）
    bdSync();
    cvtPadHide();
  });
}

/* ---- 换算界面底下那颗「体积 → 质量」：带着当前数值和单位跳过去 ----
   数值原样搬（不重新格式化），单位也搬 —— 用户在体积页填的是「12 加仑」，
   跳过去还得先改回升就太别扭了。密度仍是默认的水，改一下就是别的物质。 */
if (cvtBridgeBtn) {
  cvtBridgeBtn.addEventListener('click', () => {
    const dir = cvtBridgeBtn.dataset.dir;
    if (!dir) return;
    bdConvScroll = unitBodyEl.scrollTop;
    bdOpen(dir, { value: cvtFrom.value, unit: cvtSel.from });
  });
}

/* ---- 复制：数值 / 结果各一颗（见七、那一节） ---- */
[[cvtCopyFromBtn, cvtFrom, '数值', '复制数值'],
 [cvtCopyToBtn,   cvtTo,   '结果', '复制结果'],
 [bdCopyFromBtn,  bdFromEl, '数值', '复制数值'],
 [bdCopyToBtn,    bdToEl,   '结果', '复制结果']].forEach(([btn, input, label, aria]) => {
  btn.setAttribute('aria-label', aria);
  // 拦 mousedown：不抢输入框的焦点，否则手机上的软键盘会跟着收起来
  btn.addEventListener('mousedown', e => e.preventDefault());
  btn.addEventListener('click', () => cvtCopy(input, label));
});

/* ---- 打开单位弹窗 ---- */
cvtFromBtn.addEventListener('click', () => cvtOpenPicker('from'));
cvtToBtn.addEventListener('click', () => cvtOpenPicker('to'));
bdFromUnitBtn.addEventListener('click', () => cvtOpenPicker('bdFrom'));
bdToUnitBtn.addEventListener('click', () => cvtOpenPicker('bdTo'));
bdDensityBtn.addEventListener('click', () => cvtOpenPicker('bdRho'));

/* ---- 选中一个单位 ----
   换单位**保留**框里的数字（1 米 → 1 千米），只是按新系数重算结果 ——
   单位换算器都是这个手感：数字是用户刚敲的，不该被悄悄改掉。
   体积⇄质量那层共用这个弹窗：它有三个栏（体积 / 质量 / 密度），
   落到哪个状态由 cvtPicking 说了算。 */
unitPickerChips.addEventListener('click', e => {
  const chip = e.target.closest('.chip');
  if (!chip || !cvtPicking) return;

  const which = cvtPicking;
  const u = cvtPickSource().units.find(x => x.id === chip.dataset.unit);

  if (u) {
    if (which === 'bdFrom')      bdSel.from = u.id;
    else if (which === 'bdTo')   bdSel.to = u.id;
    else if (which === 'bdRho')  bdSel.rho = u.id;
    else                         cvtSel[which] = u.id;
  }

  cvtClosePicker();

  if (which.indexOf('bd') === 0) { bdPaintUnits(); bdSync(); }
  else { cvtPaintUnits(); cvtSync(); }
});

/* ---- 关闭弹窗：✕ / 点遮罩 ---- */
unitPickerClose.addEventListener('click', cvtClosePicker);
unitPicker.addEventListener('click', e => {
  if (e.target === unitPicker) cvtClosePicker();
});

/* ---- 顶栏返回：换算界面 / 体积⇄质量里先退回类别列表 ----
   放在**捕获阶段**：tools.js 的返回处理挂在冒泡阶段，捕获先跑，
   stopPropagation 就能把它挡下来（和 cards.js 拦卡片点击同一个套路）。 */
document.addEventListener('click', e => {
  const back = e.target.closest('[data-tool-back]');
  if (!back || back.closest('.tool-page') !== UNIT_PAGE) return;
  // cvtBackOne 顺带把「有几层可退」判断完了：返回 false 说明已经在类别页，
  // 那就别拦，交给 tools.js 去关掉整个功能页。
  if (!cvtBackOne()) return;
  e.preventDefault();
  e.stopPropagation();
}, true);

/* ---- Esc：一次只退一层（先收键盘，再关弹窗，再退类别列表） ----
   挂在 window 的捕获阶段（见文件头那段说明），才能抢在 tools.js 前面。 */
window.addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;

  if (cvtPad && !cvtPad.hidden) {     // 软键盘开着：先收它（和「完成」一个效果）
    e.stopPropagation();
    cvtPadHide();
    if (cvtPadTarget) cvtPadTarget.blur();
    return;
  }
  if (unitPicker.classList.contains('show')) {
    e.stopPropagation();
    cvtClosePicker();
    return;
  }
  if (!cvtResultsEl.hidden) {      // 搜索结果：先退回它顶掉的那一层
    e.stopPropagation();
    cvtCloseSearch();
    return;
  }
  if (!UNIT_PAGE.classList.contains('show')) return;
  if (!cvtBackOne()) return;      // 已经在类别页：交给 tools.js 关掉功能页
  e.stopPropagation();
}, true);

/* ---- 返回键（js/backnav.js）：换算界面 / 体积⇄质量里先退回类别列表 ----
   顺序和上面那条顶栏返回一致；软键盘 / 单位选择器那两层由 backnav 按层处理，
   走到这里时只剩「子视图 vs 类别列表」这一级。 */
if (typeof NovaBack !== 'undefined') {
  NovaBack.inner(top => {
    if (top !== UNIT_PAGE) return false;    // 上面还压着单位选择器时，那层先关
    return cvtBackOne();                    // 换算页 / 选量 / 类别页三级都在里面判
  });
}

/* ---- 进这个功能页：每次从「选类别」开始，并把默认状态复位 ---- */
document.addEventListener('tool:open', e => {
  if (!e.detail || e.detail.page !== UNIT_PAGE) return;
  cvtReset();
});

/* ==========================================================
   十六、初始化
   ========================================================== */
cvtPadBind();
cvtReset();
